              placeholder="在这里添加任何其他想要说明的信息，比如特殊经历、爱好、习惯等..."
            ></textarea>
          </div>
        </div>

        <!-- 底部按钮 -->
        <div class="bottom-actions">
          <button class="action-btn primary" onclick="confirmCreate()">⚔️ ✨确认角色创建✨</button>
        </div>

        <div class="completion-text">创建完成后，您将正式开启异世界冒险之旅</div>
      </div>

      <!-- 说明页面 -->
      <div class="main-panel instruction-panel" id="instructionPanel" style="display: none">
        <h1 class="title">✨ 创建完成 ✨<br>请先点击重新读取变量，再点击左上角的刷新按钮，随后发送酒馆输入框内的回复</h1>
        <p style="margin-top: 30px; font-size: 18px;">角色创建成功！欢迎来到异世界冒险之旅！</p>
      </div>
    </div>

    <script>
      // ========== 属性点管理系统 ==========
      let totalPoints = 150; // 总属性点
      let usedPoints = 0; // 已使用的属性点
      let familyMembers = []; // 家族成员列表
      let randomizeCost = 0; // 随机操作消耗的点数

// 统一的提示函数（支持 toastr 和原生 alert）
      function showNotification(message, title, type = 'info') {
        console.log(`[${type.toUpperCase()}] ${title}: ${message}`);

        if (typeof toastr !== 'undefined') {
          switch(type) {
            case 'success':
              toastr.success(message, title);
              break;
            case 'error':
              toastr.error(message, title);
              break;
            case 'warning':
              toastr.warning(message, title);
              break;
            default:
              toastr.info(message, title);
          }
        } else {
          // 备用方案：使用原生 alert
          alert(`【${title}】${message}`);
        }
      }
// 选择难度
      function selectDifficulty(points) {
        totalPoints = points;

        // 更新难度按钮状态
        document.querySelectorAll('.difficulty-btn').forEach(btn => {
          btn.classList.remove('selected');
          if (parseInt(btn.dataset.points) === points) {
            btn.classList.add('selected');
    }
  });

        updateRemainingPoints();
}

// ========== 家族成员管理系统 ==========
// 更新家族成员创建消耗
      function updateFamilyMemberCost() {
        const count = parseInt(document.getElementById('familyMemberCount').value) || 0;
        const cost = count * 10;
        document.getElementById('familyMemberCostDisplay').textContent = `消耗：${cost}点`;
      }

// 生成家族成员
      function generateFamilyMembers() {
        const count = parseInt(document.getElementById('familyMemberCount').value) || 0;

        if (count <= 0) {
          showNotification('请设置成员数量', '提示', 'warning');
          return;
        }

        const cost = count * 10;
        const remaining = totalPoints - calculateUsedPoints();

        if (remaining < cost) {
          showNotification(`属性点不足！需要 ${cost} 点，当前剩余 ${remaining} 点`, '无法创建', 'error');
          return;
        }

        // 生成成员
        for (let i = 0; i < count; i++) {
          familyMembers.push(createRandomFamilyMember());
        }

        renderFamilyMembers();
        updateRemainingPoints();
        showNotification(`成功创建 ${count} 位家族成员`, '成功', 'success');
      }

// 创建随机家族成员
      function createRandomFamilyMember() {
        const surnames = ['张', '李', '王', '赵', '陈', '刘', '杨', '黄', '周', '吴', '徐', '孙', '马', '朱', '胡', '郭', '何', '林', '罗', '宁', '玄', '云', '慕', '司徒', '上官', '欧阳'];
        const maleNames = ['云霄', '天明', '玄机', '凌霄', '逸尘', '墨轩', '宇轩', '浩然', '子墨', '辰风', '煜祺', '鸿煊'];
        const femaleNames = ['灵月', '秋月', '雪儿', '紫烟', '清雅', '婉儿', '语嫣', '诗涵', '梦琪', '雨晴', '慕容', '静雪'];

        const genders = ['男', '女'];
        const gender = genders[Math.floor(Math.random() * genders.length)];
        const namePool = gender === '男' ? maleNames : femaleNames;

        const surname = surnames[Math.floor(Math.random() * surnames.length)];
        const name = surname + namePool[Math.floor(Math.random() * namePool.length)];

        const realms = ['凡人', '胎息玄景轮', '胎息承明轮', '胎息周行轮', '胎息青元轮', '胎息玉京轮', '胎息灵初轮', '筑基前期', '筑基中期', '筑基后期'];
        const daotongs = [
          '太阴', '少阴', '厥阴', '太阳', '少阳', '明阳',
          '兑金', '逍金', '齐金', '库金', '庚金',
          '正木', '集木', '保木', '角木', '更木',
          '坎水', '府水', '合水', '牝水', '渌水',
          '离火', '真火', '并火', '牡火', '灴火',
          '艮土', '戊土', '归土', '宝土', '宣土', '青宣',
          '玄雷', '霄雷', '元雷'
        ];

        const lingqiaoPositions = ['下丹田气海穴', '中丹田膻中穴', '上丹田印堂穴', '命门', '涌泉穴'];
        const lingqiaoQualities = ['上品', '中品', '下品'];

        const identities = ['家族长老', '家族弟子', '家族执事', '家族护法', '散修', '外门弟子'];

        const age = Math.floor(Math.random() * 50) + 18; // 18-67岁
        const realm = realms[Math.floor(Math.random() * realms.length)];
        const daotong = daotongs[Math.floor(Math.random() * daotongs.length)];

        // 根据境界决定法力体力范围
        let faliRange, tiliRange;
        if (realm === '凡人') {
          faliRange = [50, 100];
          tiliRange = [80, 120];
        } else if (realm.includes('胎息')) {
          faliRange = [100, 200];
          tiliRange = [100, 150];
        } else if (realm.includes('筑基')) {
          faliRange = [200, 400];
          tiliRange = [150, 250];
        } else {
          faliRange = [100, 300];
          tiliRange = [100, 200];
        }

        const faliMax = Math.floor(Math.random() * (faliRange[1] - faliRange[0])) + faliRange[0];
        const tiliMax = Math.floor(Math.random() * (tiliRange[1] - tiliRange[0])) + tiliRange[0];

        // 随机天赋（最多3个）
        const allTalents = [
          '悟性超凡', '灵觉敏锐', '神识强大', '法力深厚', '肉身强健',
          '御剑天赋', '神通领悟', '法术精通', '阵法造诣', '符箓天赋',
          '炼丹天才', '炼器大师', '炼药造诣', '禁制精通',
          '御兽天赋', '灵植培育', '驯化妖兽',
          '卜算之术', '观星推演', '医术通神', '毒道精通', '机关巧术',
          '琴道造诣', '棋道精通', '书法天赋', '丹青妙笔',
          '古籍通晓', '灵石鉴定', '遁法精通', '隐匿气息', '灵觉避险', '天机感应'
        ];
        const talentCount = Math.floor(Math.random() * 3) + 1; // 1-3个天赋
        const selectedTalents = getRandomItems([...allTalents], talentCount);

        return {
          姓名: name,
          年龄: age,
          性别: gender,
          身份: identities[Math.floor(Math.random() * identities.length)],
          心跳: Math.floor(Math.random() * 20) + 70, // 70-90
          好感度: Math.floor(Math.random() * 60) + 20, // 20-80
          境界: realm,
          道统: daotong,
          灵窍位置: lingqiaoPositions[Math.floor(Math.random() * lingqiaoPositions.length)],
          灵窍品质: lingqiaoQualities[Math.floor(Math.random() * lingqiaoQualities.length)],
          法力值: faliMax,
          法力上限: faliMax,
          体力值: tiliMax,
          体力上限: tiliMax,
          天赋: selectedTalents
        };
      }

// 渲染家族成员列表
      function renderFamilyMembers() {
        const container = document.getElementById('familyMembersList');
        if (!container) return;

        if (familyMembers.length === 0) {
          container.innerHTML = '<div style="text-align: center; padding: 20px; opacity: 0.6;">暂无家族成员</div>';
          return;
        }

        container.innerHTML = familyMembers.map((member, index) => `
          <div style="background: rgba(212, 175, 55, 0.1); border: 2px solid #8b6914; border-radius: 8px; padding: 15px; margin-bottom: 10px;">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;">
              <div style="font-size: 16px; font-weight: bold; color: #d4af37;">
                ${index + 1}. ${member.姓名} (${member.性别}, ${member.年龄}岁)
              </div>
              <div style="display: flex; gap: 5px;">
                <button class="option-btn" onclick="randomizeFamilyMember(${index})" style="padding: 5px 10px; font-size: 12px;" title="随机此成员 (5点)">
                  ⚅
                </button>
                <button class="option-btn" onclick="removeFamilyMember(${index})" style="padding: 5px 10px; font-size: 12px; background: rgba(239, 68, 68, 0.2);" title="删除">
                  ✕
                </button>
              </div>
            </div>
            <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 8px; font-size: 15px;">
              <div><span style="opacity: 0.7;">身份：</span>${member.身份}</div>
              <div><span style="opacity: 0.7;">好感度：</span>${member.好感度}</div>
              <div><span style="opacity: 0.7;">境界：</span>${member.境界}</div>
              <div><span style="opacity: 0.7;">道统：</span>${member.道统}</div>
              <div><span style="opacity: 0.7;">灵窍：</span>${member.灵窍品质}（${member.灵窍位置}）</div>
              <div><span style="opacity: 0.7;">法力：</span>${member.法力值}/${member.法力上限}</div>
              <div><span style="opacity: 0.7;">体力：</span>${member.体力值}/${member.体力上限}</div>
              <div style="grid-column: 1 / -1;"><span style="opacity: 0.7;">天赋：</span>${member.天赋.join('、')}</div>
            </div>
          </div>
        `).join('');
      }

// 随机单个家族成员
      function randomizeFamilyMember(index) {
        const remaining = totalPoints - calculateUsedPoints();
        if (remaining < 5) {
          showNotification('属性点不足！随机需要 5 点', '无法随机', 'error');
          return;
        }

        randomizeCost += 5; // 消耗5点
        familyMembers[index] = createRandomFamilyMember();
        renderFamilyMembers();
        updateRemainingPoints();
        showNotification(`已随机成员 ${index + 1}，消耗5点`, '成功', 'success');
      }

// 随机所有家族成员
      function randomizeAllFamilyMembers() {
        if (familyMembers.length === 0) {
          showNotification('请先创建家族成员', '提示', 'warning');
          return;
        }

        const remaining = totalPoints - calculateUsedPoints();
        if (remaining < 5) {
          showNotification('属性点不足！随机需要 5 点', '无法随机', 'error');
          return;
        }

        randomizeCost += 5; // 消耗5点
        familyMembers = familyMembers.map(() => createRandomFamilyMember());
        renderFamilyMembers();
        updateRemainingPoints();
        showNotification(`已随机所有家族成员，消耗5点`, '成功', 'success');
      }

// 删除家族成员
      function removeFamilyMember(index) {
        if (confirm(`确定删除 ${familyMembers[index].姓名} 吗？`)) {
          familyMembers.splice(index, 1);
          renderFamilyMembers();
          updateRemainingPoints();
          showNotification('已删除成员，返还10点', '成功', 'success');
        }
      }

// 计算已使用的属性点
      function calculateUsedPoints() {
        let used = 0;

        // 开场消耗
        const starting = document.querySelector('#startingGrid .option-btn.selected');
        if (starting) {
          used += parseInt(starting.dataset.cost) || 0;
        }

        // 道统消耗
        const identity = document.querySelector('#identityGrid .option-btn.selected');
        if (identity) {
          used += parseInt(identity.dataset.cost) || 0;
        }

        // 出生地消耗
        const birthplace = document.querySelector('#birthplaceGrid .option-btn.selected');
        if (birthplace) {
          used += parseInt(birthplace.dataset.cost) || 0;
        }

        // 特殊建筑消耗
        const specialBuilding = document.querySelector('#specialBuildingGrid .option-btn.selected');
        if (specialBuilding) {
          used += parseInt(specialBuilding.dataset.cost) || 0;
        }

        // 技能消耗
        const skills = document.querySelectorAll('#skillsGrid .option-btn.selected');
        skills.forEach(skill => {
          used += parseInt(skill.dataset.cost) || 0;
        });

        // 家族成员消耗：每位成员10点
        used += familyMembers.length * 10;

        // 随机操作消耗
        used += randomizeCost;

        return used;
}
// 更新剩余属性点显示
      function updateRemainingPoints() {
        usedPoints = calculateUsedPoints();
        const remaining = totalPoints - usedPoints;
        const pointsDisplay = document.getElementById('remainingPoints');

        if (pointsDisplay) {
          pointsDisplay.textContent = remaining;

          // 根据剩余点数改变颜色
          if (remaining < 0) {
            pointsDisplay.style.color = '#ef4444'; // 红色
          } else if (remaining < 20) {
            pointsDisplay.style.color = '#f59e0b'; // 橙色
          } else {
            pointsDisplay.style.color = '#4ade80'; // 绿色
          }
        }
}
// 折叠功能
      function toggleCollapse(sectionName) {
        console.log('toggleCollapse called with:', sectionName);
        const header = document.querySelector(`#${sectionName}Section .collapsible-header`);
        const content = document.querySelector(`#${sectionName}Content`);
        const selectedItems = document.querySelector(`#${sectionName}Selected`);

        console.log('Elements found:', { header, content, selectedItems });

        if (header && content) {
        header.classList.toggle('collapsed');
        content.classList.toggle('collapsed');
          console.log('Toggled classes. Header collapsed:', header.classList.contains('collapsed'));
          console.log('Content collapsed:', content.classList.contains('collapsed'));

        // 如果折叠且有选中项，显示选中项
          if (selectedItems) {
        if (header.classList.contains('collapsed') && selectedItems.children.length > 0) {
          selectedItems.classList.add('show');
  } else {
          selectedItems.classList.remove('show');
            }
          }
        } else {
          console.error('Could not find elements for section:', sectionName);
  }
}
// 更新选中项显示
      function updateSelectedItems(sectionName) {
        const grid = document.getElementById(sectionName + 'Grid');
        const selectedContainer = document.getElementById(sectionName + 'Selected');

        if (!grid || !selectedContainer) return;

        const selectedBtns = grid.querySelectorAll('.option-btn.selected');
        const customInput = document.getElementById(sectionName + 'Custom');
        selectedContainer.innerHTML = '';

        // 显示选中的选项
        selectedBtns.forEach(btn => {
          const item = document.createElement('div');
          item.className = 'selected-item';

          // 特殊处理系统原因和开场选项，显示标题而不是data-value
          if ((sectionName === 'systemReason' || sectionName === 'starting') && btn.classList.contains('system-reason-option')) {
            const titleElement = btn.querySelector('.system-reason-title');
            item.textContent = titleElement ? titleElement.textContent : btn.getAttribute('data-value');
    } else {
            item.textContent = btn.getAttribute('data-value');
    }

          selectedContainer.appendChild(item);
  });

        // 显示自定义输入的内容
        if (customInput && customInput.value.trim()) {
          const customItems = customInput.value
            .split(',')
            .map(s => s.trim())
            .filter(s => s);
          customItems.forEach(customValue => {
            const item = document.createElement('div');
            item.className = 'selected-item';
            item.style.backgroundColor = '#c084fc'; // 紫色背景区分自定义输入
            item.textContent = customValue;
            selectedContainer.appendChild(item);
    });
  }
  // 更新折叠状态显示
        const header = document.querySelector(`#${sectionName}Section .collapsible-header`);
        if (header && header.classList.contains('collapsed')) {
          const hasSelectedItems = selectedBtns.length > 0 || (customInput && customInput.value.trim());
          if (hasSelectedItems) {
            selectedContainer.classList.add('show');
    } else {
            selectedContainer.classList.remove('show');
    }
  }
}
// 获取当前性别
      function getCurrentGender() {
        const biologicalGender = document.getElementById('biologicalGender').value;
        return biologicalGender;
}
// 根据性别获取穿搭选项范围
// 检查字段是否已有用户主动选择的值
      function hasUserValue(fieldName) {
        const element = document.getElementById(fieldName);
        if (element) {
          if (
            element.type === 'number' ||
            element.tagName === 'INPUT' ||
            element.tagName === 'SELECT' ||
            element.tagName === 'TEXTAREA'
          ) {
            return element.value && element.value.trim() !== '' && element.dataset.userSelected === 'true';
    }
  }
  // 检查多选选项
        const grid = document.getElementById(fieldName + 'Grid');
        if (grid) {
          const userSelectedBtns = grid.querySelectorAll('.option-btn.selected[data-user-selected="true"]');
          if (userSelectedBtns.length > 0) return true;
  }
  // 检查自定义输入
        const customInput = document.getElementById(fieldName + 'Custom');
        if (
          customInput &&
          customInput.value &&
          customInput.value.trim() !== '' &&
          customInput.dataset.userSelected === 'true'
        ) {
          return true;
  }

        return false;
}
// 检查字段是否已有值（不区分用户选择还是随机生成）
      function hasValue(fieldName) {
        const element = document.getElementById(fieldName);
        if (element) {
          if (
            element.type === 'number' ||
            element.tagName === 'INPUT' ||
            element.tagName === 'SELECT' ||
            element.tagName === 'TEXTAREA'
          ) {
            return element.value && element.value.trim() !== '';
    }
  }
  // 检查多选选项
        const grid = document.getElementById(fieldName + 'Grid');
        if (grid) {
          const selectedBtns = grid.querySelectorAll('.option-btn.selected');
          if (selectedBtns.length > 0) return true;
  }
  // 检查自定义输入
        const customInput = document.getElementById(fieldName + 'Custom');
        if (customInput && customInput.value && customInput.value.trim() !== '') {
          return true;
  }

        return false;
}
// 随机化字段功能
      function randomizeField(fieldName, force = false) {
        // 如果不是强制模式且有用户主动选择的值，则跳过
        if (!force && hasUserValue(fieldName)) {
          return;
        }

        const randomData = {
          age: () => Math.floor(Math.random() * 18) + 18, // 18-35岁
          gender: () => ['男', '女', '扶她'][Math.floor(Math.random() * 3)],
          skills: () => {
            const skills = [
              // 修炼天赋
              '悟性超凡', '灵觉敏锐', '神识强大', '法力深厚', '肉身强健',
              // 战斗天赋
              '御剑天赋', '神通领悟', '法术精通', '阵法造诣', '符箓天赋',
              // 炼制天赋
              '炼丹天才', '炼器大师', '炼药造诣', '禁制精通',
              // 灵兽相关
              '御兽天赋', '灵植培育', '驯化妖兽',
              // 辅助天赋
              '卜算之术', '观星推演', '医术通神', '毒道精通', '机关巧术',
              // 修仙百艺
              '琴道造诣', '棋道精通', '书法天赋', '丹青妙笔',
              // 特殊天赋
              '古籍通晓', '灵石鉴定', '遁法精通', '隐匿气息', '灵觉避险', '天机感应'
            ];
            return getRandomItems(skills, Math.floor(Math.random() * 3) + 1);
          },
        };

        if (randomData[fieldName]) {
          const value = randomData[fieldName]();

          if (Array.isArray(value)) {
            // 处理多选选项
            const grid = document.getElementById(fieldName + 'Grid');
            if (grid) {
              // 清除所有选择
              grid.querySelectorAll('.option-btn').forEach(btn => btn.classList.remove('selected'));
              // 选择随机项
              value.forEach(item => {
                const btn = grid.querySelector(`[data-value="${item}"]`);
                if (btn) btn.classList.add('selected');
              });
              // 更新选中项显示
              updateSelectedItems(fieldName);
            }
          } else {
            // 处理单选项和数值项
            const element = document.getElementById(fieldName);
            if (element) {
              element.value = value;
            }
          }
        }

        // 特殊处理身高体重的随机值
        if (fieldName === 'age') {
          const ageElement = document.getElementById('age');
          if (ageElement) {
            ageElement.value = Math.floor(Math.random() * 18) + 18; // 18-35岁
          }
        } else if (fieldName === 'height') {
          const heightElement = document.getElementById('height');
          const genderElement = document.getElementById('gender');
          const gender = genderElement ? genderElement.value : '';
          if (heightElement) {
            if (gender === '女' || gender === '扶她') {
              heightElement.value = Math.floor(Math.random() * 41) + 150; // 150-190cm
            } else if (gender === '男') {
              heightElement.value = Math.floor(Math.random() * 41) + 165; // 165-205cm
            } else {
              heightElement.value = Math.floor(Math.random() * 56) + 150; // 150-205cm
            }
          }
        } else if (fieldName === 'weight') {
          const weightElement = document.getElementById('weight');
          const genderElement = document.getElementById('gender');
          const gender = genderElement ? genderElement.value : '';
          if (weightElement) {
            if (gender === '女' || gender === '扶她') {
              weightElement.value = Math.floor(Math.random() * 31) + 45; // 45-75kg
            } else if (gender === '男') {
              weightElement.value = Math.floor(Math.random() * 41) + 60; // 60-100kg
            } else {
              weightElement.value = Math.floor(Math.random() * 56) + 45; // 45-100kg
            }
          }
        }
}
// 获取随机项目
      function getRandomItems(array, count) {
        const shuffled = array.sort(() => 0.5 - Math.random());
        return shuffled.slice(0, count);
}
// 经历部分的随机化
      function randomizeExperienceField(fieldName, force = false) {
