                // 如果是要选中（而不是取消选中），检查属性点是否足够
                if (!wasSelected && itemCost > 0) {
                  const currentUsed = calculateUsedPoints();
                  const currentRemaining = totalPoints - currentUsed;

                  // 对于单选模式，计算替换后的消耗
                  if (grid.classList.contains('single-select')) {
                    const currentSelected = grid.querySelector('.option-btn.selected');
                    const currentCost = currentSelected ? (parseInt(currentSelected.dataset.cost) || 0) : 0;
                    const netCost = itemCost - currentCost; // 新增消耗 = 新选项成本 - 旧选项成本

                    if (currentRemaining - netCost < 0) {
                      showNotification(`该选项需要 ${itemCost} 点，当前剩余 ${currentRemaining} 点`, '属性点不足！', 'error');
