/* --- 范围滑块 --- */
input[type="range"] {
    -webkit-appearance: none !important;
    appearance: none !important;
    height: 2px !important;
    background: #333 !important;
    border-radius: 1px !important;
}

/* --- 修改部分: WebKit浏览器 (Chrome, Safari, Edge) --- */
input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none !important;
    width: 14px !important;  /* 调整尺寸以使菱形视觉上大小合适 */
    height: 14px !important; /* 调整尺寸以使菱形视觉上大小合适 */
    background: #000 !important; /* 修改为黑底 */
    border: 1px solid #555 !important; /* 修改为1px白色边框 */
    border-radius: 0 !important; /* 移除圆角以形成方形基础 */
    box-shadow: 0 2px 5px rgba(0, 0, 0, 0.8) !important; /* 保留阴影 */
    transform: rotate(45deg); /* 旋转45度形成菱形 */
    transition: all 0.2s ease !important;
    margin-top: -2px; /* 垂直居中补偿 */
}

input[type="range"]::-webkit-slider-thumb:hover {
    transform: rotate(45deg) scale(1.15) !important; /* 悬停时在旋转的基础上放大 */
    background: #222 !important; /* 悬停时背景变亮一些 */
    box-shadow: 
        0 3px 8px rgba(0, 0, 0, 0.7), 
        0 0 10px rgba(255, 255, 255, 0.3) !important; /* 增加白色辉光效果 */
}

/* --- 修改部分: Mozilla浏览器 (Firefox) --- */
input[type="range"]::-moz-range-thumb {
    width: 14px !important;
    height: 14px !important;
    background: #000 !important; /* 修改为黑底 */
    border: 1px solid #555 !important; /* 修改为1px白色边框 */
    border-radius: 0 !important; /* 移除圆角，在Firefox中将显示为正方形 */
    box-shadow: 
        0 2px 5px rgba(0, 0, 0, 0.8),
        inset 0 -2px 1px rgba(0, 0, 0, 0.3) !important;
    /* Firefox不支持在thumb上使用transform, 所以这里无法旋转成菱形 */
}

.neo-range-slider {
    background: #181818 !important;
    border-radius: 8px !important;
    border: 1px solid #000 !important;
    box-shadow: 
        inset 0 0 15px rgba(0, 0, 0, 0.9),
        0 1px 0 rgba(255, 255, 255, 0.04) !important;
}

.text_pole:hover,
textarea:hover,
select:hover,
.neo-range-input:hover {
    border-color: rgba(255, 255, 255, 0.5) !important;
    box-shadow: 
        inset 0 2px 6px rgba(0, 0, 0, 0.7),
        0 0 5px rgba(255, 255, 255, 0.08) !important;
}
