/* ==================== Tab内容区域 ==================== */
.village-tab-content {
    position: relative;
    max-height: 70vh;
    overflow-y: auto;
    overflow-x: hidden;
    padding: 15px;
    background: rgba(245, 235, 215, 0.3);
