    border: 1px solid #8b4513;
    box-shadow: inset 0 0 3px rgba(139, 69, 19, 0.3);
}

.village-tab-content::-webkit-scrollbar-thumb:hover {
    background: linear-gradient(180deg, #c13832 0%, #a52a2a 100%);
}

.village-panel-wrapper {
    display: none;
}

.village-panel-wrapper.active {
    display: block;
    animation: fadeIn 0.3s ease-out;
}

/* ==================== 从原城中村样式继承的面板样式 ==================== */
/* 这些样式保持原有的城中村面板样式 */

.section {
    background: linear-gradient(135deg, rgba(250, 245, 230, 0.85) 0%, rgba(245, 235, 215, 0.9) 100%);
    border: 2px solid #d4a574;
    border-radius: 8px;
    margin-bottom: 15px;
    overflow: hidden;
    box-shadow: 0 3px 8px rgba(139, 69, 19, 0.25);
