    const myCultivation = myInfoData.修炼信息 || {};
    const myEquippedFabao = myInfoData.装备法宝 || {};
    const myPower = calculateCultivatorPower(myCultivation, '', myEquippedFabao);

    const generators = {
        myInfo: (data) => generateMyInfo(data, myPower),
        familyInfo: (data) => generateFamilyInfo(data, statData),
        items: generateItems,
        auctionHouse: (data) => generateAuctionHouse(data, statData['家族信息']?.['灵石']?.[0] || 0),
        characterBonds: (data) => generateCharacterBonds(data, myPower),
        currentTargets: (data) => generateCurrentTargets(data, myPower),
        familyBuildings: generateFamilyBuildings,
        map: generateMap,
        plot: generatePlot
    };

    // 生成Tab标签
    let tabsHtml = '';
    let panelsHtml = '';
    let firstTab = true;

    Object.entries(VILLAGE_CONFIG.fields).forEach(([key, config]) => {
        const dataFieldName = config.name;
        const icon = config.icon || '📋';
        const generator = generators[key];

        if (!generator) {
            console.warn(`⚠️ 没有找到"${key}"的生成器`);
            return;
        }

        const fieldData = statData[dataFieldName] || {};
        if (!statData[dataFieldName]) {
            console.warn(`⚠️ 没有找到"${dataFieldName}"数据，将显示空状态`);
        }

        // 生成Tab标签
        tabsHtml += `
            <div class="village-tab ${firstTab ? 'active' : ''}" data-tab="${key}">
                <span>${icon}</span>
                <span>${dataFieldName}</span>
            </div>
        `;

        // 生成Tab内容
        let panelContent;
        try {
            panelContent = generator(fieldData);
        } catch (error) {
            console.error(`❌ 生成"${dataFieldName}"面板时出错:`, error);
            panelContent = `
                <div class="section">
                    <div class="section-title" style="color: #ef4444;">⚠️ ${dataFieldName}</div>
                    <div class="section-content">
