// ==================== 辅助函数 ====================
function safeGetArray(data, defaultValue = []) {
    try {
        if (Array.isArray(data)) {
            return data.filter(item => item !== '$__META_EXTENSIBLE__$');
        } else if (data && typeof data === 'string') {
            return [data];
        } else if (data === null || data === undefined) {
            return defaultValue;
        } else {
            console.warn('⚠️ 数据不是数组，尝试转换:', data);
            return defaultValue;
        }
    } catch (e) {
        console.warn('⚠️ 处理数组数据时出错:', e);
        return defaultValue;
    }
}

// ==================== 战斗力计算系统 ====================

// 计算境界基础值
function getRealmBaseValue(realm) {
    // 大幅拉开境界差距，确保不会出现跨阶战胜的情况
    if (realm.includes('胎息')) {
        // 胎息：10-60，根据轮数
        const match = realm.match(/([一二三四五六])轮/);
        if (match) {
            const lunMap = {'一': 1, '二': 2, '三': 3, '四': 4, '五': 5, '六': 6};
            const lunCount = lunMap[match[1]] || 1;
            return 10 + lunCount * 8;
        }
        return 35; // 默认中期
    } else if (realm.includes('练气')) {
        // 练气：100-200，是胎息的3-4倍
        return realm.includes('圆满') ? 200 : realm.includes('后期') ? 180 : realm.includes('中期') ? 150 : 120;
    } else if (realm.includes('筑基')) {
        // 筑基：600-1200，是练气的5-6倍
        return realm.includes('圆满') ? 1200 : realm.includes('后期') ? 1000 : realm.includes('中期') ? 800 : 600;
    } else if (realm.includes('紫府')) {
        // 紫府：4000-8000，是筑基的6-7倍，度过参紫为大真人
        return realm.includes('参紫') || realm.includes('大真人') ? 8000 : 5000;
    } else if (realm.includes('金丹')) {
        // 金丹：30000-60000，是紫府的7-8倍，果位>余位>润位
        if (realm.includes('果位')) return 60000;
        if (realm.includes('余位')) return 45000;
        if (realm.includes('润位')) return 35000;
        return 45000;
    } else if (realm.includes('元婴') || realm.includes('道胎')) {
        // 道胎：350000+，是金丹的8-10倍
        return 400000;
    } else if (realm.includes('凡人')) {
        return 1; // 凡人基础值
    }
    return 1;
}

// 获取道统相克关系
function getDaotongCounterEffect(myDaotong, enemyDaotong) {
    if (!myDaotong || !enemyDaotong) return 1.0;

    // 五行相克
    const wuxingMap = {
        '金': ['兑金', '逍金', '齐金', '库金', '庚金'],
        '木': ['正木', '集木', '角木', '更木', '保木'],
        '水': ['坎水', '府水', '合水', '牝水', '渌水'],
        '火': ['离火', '真火', '并火', '牡火', '灴火'],
        '土': ['艮土', '戊土', '归土', '宝土', '宣土', '青宣']
    };

    let myWuxing = '';
    let enemyWuxing = '';

    for (const [wuxing, daotongs] of Object.entries(wuxingMap)) {
        if (daotongs.some(dt => myDaotong.includes(dt))) myWuxing = wuxing;
        if (daotongs.some(dt => enemyDaotong.includes(dt))) enemyWuxing = wuxing;
    }

    // 五行相克关系
    const counterMap = {
        '金': '木',  // 金克木
        '木': '土',  // 木克土
        '土': '水',  // 土克水
        '水': '火',  // 水克火
        '火': '金'   // 火克金
    };

    if (myWuxing && enemyWuxing) {
        if (counterMap[myWuxing] === enemyWuxing) {
            return 1.15; // 我克制对方，+15%
        } else if (counterMap[enemyWuxing] === myWuxing) {
            return 0.85; // 对方克制我，-15%
        }
    }

    // 阴阳相克
    if (myDaotong.includes('太阳') && enemyDaotong.includes('太阴')) return 1.1;
    if (myDaotong.includes('太阴') && enemyDaotong.includes('太阳')) return 0.9;
    if (myDaotong.includes('少阳') && enemyDaotong.includes('少阴')) return 1.1;
    if (myDaotong.includes('少阴') && enemyDaotong.includes('少阳')) return 0.9;

    return 1.0; // 无相克关系
}

// 计算修炼者战斗力（适用于所有修士）
function calculateCultivatorPower(cultivationInfo, enemyDaotong = '', equippedFabao = null) {
    const realm = cultivationInfo.境界?.[0] || '未知';
    const realmDetail = cultivationInfo.境界详情?.[0] || '';
    const daotong = cultivationInfo.道统?.[0] || '';

    // 1. 境界基础值
    const baseValue = getRealmBaseValue(realmDetail || realm);

    // 2. 修为系数
    let progressRatio = 0.5; // 默认中期
    if (realmDetail.includes('初期') || realmDetail.includes('初')) progressRatio = 0.3;
    if (realmDetail.includes('中期') || realmDetail.includes('中')) progressRatio = 0.5;
    if (realmDetail.includes('后期') || realmDetail.includes('后')) progressRatio = 0.7;
    if (realmDetail.includes('圆满')) progressRatio = 0.95;

    const lingqiao = cultivationInfo.灵窍 || {};
    const lingqiaoQuality = lingqiao.品质?.[0] || '中品';
    const lingqiaoBonus = lingqiaoQuality === '上品' ? 0.3 : lingqiaoQuality === '中品' ? 0.2 : 0.1;

    const xiuweiCoef = 1 + (progressRatio * 0.5) + lingqiaoBonus;

    // 3. 神通/仙基/法术加成（读取AI填写的威力值）
    let totalPower = 0;

    // 筑基：读取仙基威力
    if (realm.includes('筑基')) {
        const xianji = cultivationInfo.仙基 || {};
        const xianjiPower = xianji.威力?.[0] || 0;
        totalPower += xianjiPower;
    } 
    // 紫府及以上：读取神通威力
    else if (realm.includes('紫府') || realm.includes('金丹') || realm.includes('元婴') || realm.includes('道胎')) {
        const shentongData = cultivationInfo.神通 || {};
        const shentongKeys = Object.keys(shentongData).filter(k => k !== '$meta');
        shentongKeys.forEach(stKey => {
            const st = shentongData[stKey];
            const stPower = st.威力?.[0] || 0;
            totalPower += stPower;
        });
    }

    // 法术威力
    const fashuData = cultivationInfo.法术 || {};
    const fashuKeys = Object.keys(fashuData).filter(k => k !== '$meta');
    fashuKeys.forEach(fsKey => {
        const fs = fashuData[fsKey];
        const fsPower = fs.威力?.[0] || 0;
        totalPower += fsPower * 0.5; // 法术威力算50%
    });

    const powerJiacheng = 1 + (totalPower / 100);

    // 4. 装备法宝加成（百分比加成）
    let fabaoMultiplier = 1.0;

    // 优先使用传入的装备法宝数据（玩家的 我的信息.装备法宝）
    if (equippedFabao) {
        const fabaoKeys = Object.keys(equippedFabao).filter(k => k !== '$meta' && equippedFabao[k] !== null);
        fabaoKeys.forEach(fbKey => {
            const fb = equippedFabao[fbKey];
            const fbPowerBoost = fb.战力提升?.[0] || 0;
            fabaoMultiplier += fbPowerBoost / 100; // 百分比转换，如10表示10%即0.1
        });
    } 
    // 回退到旧的 cultivationInfo.法宝灵器（家族成员和当前目标用的）
    else {
    const fabaoData = cultivationInfo.法宝灵器 || {};
    const fabaoKeys = Object.keys(fabaoData).filter(k => k !== '$meta');
    fabaoKeys.forEach(fbKey => {
        const fb = fabaoData[fbKey];
        const fbGrade = fb.品级?.[0] || '';
        const fbBenming = fb.是否本命?.[0] || false;

        let fbBonus = 0;
            if (fbGrade === '法器') fbBonus = 0.05; // 5%
            else if (fbGrade === '灵器') fbBonus = 0.1; // 10%
            else if (fbGrade === '宝器') fbBonus = 0.2; // 20%
            else if (fbGrade === '真宝') fbBonus = 0.4; // 40%
            else if (fbGrade === '道宝') fbBonus = 0.8; // 80%

        if (fbBenming) fbBonus *= 1.5; // 本命法宝1.5倍
            fabaoMultiplier += fbBonus;
    });
    }

    // 5. 法力和体力影响
    const fali = cultivationInfo.法力值?.[0] || 0;
    const faliMax = cultivationInfo.法力上限?.[0] || 1;
    const tili = cultivationInfo.体力值?.[0] || 0;
    const tiliMax = cultivationInfo.体力上限?.[0] || 1;

    const faliRatio = Math.max(0.5, fali / faliMax); // 法力最低按50%算
    const tiliRatio = Math.max(0.6, tili / tiliMax); // 体力最低按60%算
    const zhuangtaiCoef = (faliRatio * 0.6 + tiliRatio * 0.4); // 法力占60%，体力占40%

    // 6. 道统修正
    let daotongXiuzheng = 1.0;
    if (daotong.includes('太阴') || daotong.includes('太阳') || daotong.includes('少阴') || daotong.includes('少阳')) {
        daotongXiuzheng = 1.1; // 阴阳道统
    } else if (daotong.includes('玄雷') || daotong.includes('霄雷') || daotong.includes('元雷')) {
        daotongXiuzheng = 1.2; // 雷系道统攻击强
    }

    // 太虚运用加成
    const taixu = cultivationInfo.太虚运用?.[0] || '';
    if (taixu === '完美') daotongXiuzheng *= 1.3;
    else if (taixu === '精通') daotongXiuzheng *= 1.2;
    else if (taixu === '熟练') daotongXiuzheng *= 1.15;
    else if (taixu === '初窥') daotongXiuzheng *= 1.1;

    // 金丹境特殊加成
    const jinxing = cultivationInfo.金性 || {};
    const jinxingType = jinxing.类型?.[0] || '';
    if (jinxingType === '果位') {
        daotongXiuzheng *= 1.2;
    } else if (jinxingType === '余位') {
        daotongXiuzheng *= 1.1;
    } else if (jinxingType === '润位') {
        daotongXiuzheng *= 1.05;
    }

    // 道胎持果兼余加成
    if (realm.includes('道胎') || realm.includes('元婴')) {
        if (realmDetail.includes('持') && realmDetail.includes('兼')) {
            daotongXiuzheng *= 1.3;
        }
    }

    // 7. 道统相克（如果提供了敌方道统）
    const daotongCounterEffect = getDaotongCounterEffect(daotong, enemyDaotong);

    // 最终计算
    const basePower = baseValue * xiuweiCoef * powerJiacheng * daotongXiuzheng * zhuangtaiCoef * daotongCounterEffect;
    const finalPower = basePower * fabaoMultiplier; // 法宝提供百分比加成

    return finalPower;
}

