// ========== 生成家族信息 ==========
function generateFamilyInfo(familyInfo, statData) {
    // 基本信息
    const familyName = familyInfo.家族名称?.[0] || '玄鉴仙族';
    const reputation = familyInfo.家族名声?.[0] || '默默无名';
    const memberCount = familyInfo.家族人数?.[0] || 0;
    const lingshi = familyInfo.灵石?.[0] || 0;

    // 统计道具数量（通过脚本自动计算）
    const itemsData = statData?.['道具'] || {};
    const lingziCount = Object.keys(itemsData['灵资'] || {}).filter(k => k !== '$meta' && itemsData['灵资'][k] !== null).length;
    const faqiCount = Object.keys(itemsData['法器'] || {}).filter(k => k !== '$meta' && itemsData['法器'][k] !== null).length;
    const zawuCount = Object.keys(itemsData['杂物'] || {}).filter(k => k !== '$meta' && itemsData['杂物'][k] !== null).length;
    const gongfaCount = Object.keys(itemsData['功法'] || {}).filter(k => k !== '$meta' && itemsData['功法'][k] !== null).length;
    const fashuCount = Object.keys(itemsData['法术'] || {}).filter(k => k !== '$meta' && itemsData['法术'][k] !== null).length;

    // 控制区域
    const controlAreas = safeGetArray(familyInfo.控制区域?.[0]);

    // 已接触势力
    const contactedForces = familyInfo.已接触势力 || {};
    const forceKeys = Object.keys(contactedForces).filter(k => k !== '$meta');

    return `
    <div class="section">
        <div class="section-title">🏛️ ${familyName}</div>
        <div class="section-content">
            <div class="world-bar">
                <!-- 家族名声 -->
                <div class="world-item">
                    <span class="world-label">⭐ 名声</span>
                    <span class="world-value">${reputation}</span>
                </div>

                <!-- 家族人数 -->
                <div class="world-item">
                    <span class="world-label">👥 人数</span>
                    <span class="world-value">${memberCount}人</span>
                </div>

                <!-- 灵石 -->
                <div class="world-item">
                    <span class="world-label">💎 灵石</span>
                    <span class="world-value">${lingshi}块</span>
                </div>

                <!-- 道具统计 -->
                <div class="world-item">
                    <span class="world-label">💊 灵资</span>
                    <span class="world-value">${lingziCount}件</span>
                </div>
                <div class="world-item">
                    <span class="world-label">⚔️ 法器</span>
                    <span class="world-value">${faqiCount}件</span>
                </div>
                <div class="world-item">
                    <span class="world-label">📦 杂物</span>
                    <span class="world-value">${zawuCount}件</span>
                </div>
                <div class="world-item">
                    <span class="world-label">📜 功法</span>
                    <span class="world-value">${gongfaCount}部</span>
            </div>
                <div class="world-item">
                    <span class="world-label">✨ 法术</span>
                    <span class="world-value">${fashuCount}门</span>
                </div>
            </div>

            <!-- 控制区域 -->
            <div style="margin-top: 15px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">🗺️ 控制区域 (${controlAreas.length}处)</div>
                ${controlAreas.length > 0 ? `
                <div style="display: flex; flex-wrap: wrap; gap: 6px;">
                    ${controlAreas.map(area => `
                        <div style="padding: 4px 10px; background: rgba(212, 165, 116, 0.3); border-radius: 4px; color: #8b6914; font-size: 14px; font-weight: 600; border: 1px solid #d4a574;">
                            ${area}
                        </div>
                    `).join('')}
                </div>
                ` : `
                <div style="padding: 20px; text-align: center; color: #9ca3af; font-size: 14px; background: rgba(255, 255, 255, 0.03); border-radius: 6px;">
                    暂无控制区域
                </div>
                `}
            </div>

            <!-- 已接触势力 -->
            <div style="margin-top: 15px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">🤝 已接触势力 (${forceKeys.length}个)</div>
                ${forceKeys.length > 0 ? `
                <div style="display: flex; flex-direction: column; gap: 8px;">
                    ${forceKeys.map(forceName => {
                        const force = contactedForces[forceName];
                        const relation = force.关系?.[0] || '未知';
                        const desc = force.描述?.[0] || '';

                        // 根据关系类型显示不同颜色
                        let relationColor = '#9ca3af';
                        if (relation.includes('归附') || relation.includes('友好') || relation.includes('盟友')) {
                            relationColor = '#22c55e';
                        } else if (relation.includes('敌对') || relation.includes('仇视') || relation.includes('战争')) {
                            relationColor = '#ef4444';
                        } else if (relation.includes('中立') || relation.includes('平和')) {
                            relationColor = '#fbbf24';
                        }

                        return `
                        <div style="padding: 8px 12px; background: rgba(245, 235, 215, 0.3); border-radius: 8px; border-left: 3px solid ${relationColor};">
                            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
                                <span style="color: #8b4513; font-weight: 600; font-size: 14px;">${forceName}</span>
                                <span style="color: ${relationColor}; font-size: 14px;">${relation}</span>
                            </div>
                            ${desc ? `<div style="color: #a0826d; font-size: 14px;">${desc}</div>` : ''}
                        </div>
                        `;
                    }).join('')}
                </div>
                ` : `
                <div style="padding: 20px; text-align: center; color: #a0826d; font-size: 14px; background: rgba(245, 235, 215, 0.3); border-radius: 6px;">
                    暂无接触势力
                </div>
                `}
            </div>
        </div>
    </div>
    `;
}

// ========== 生成道具 ==========
function generateItems(itemsData) {
    if (!itemsData) {
        return `
        <div class="section">
            <div class="section-title">🎁 道具</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">暂无道具数据</div>
            </div>
        </div>
        `;
    }

    // 辅助函数：获取品级颜色class
    function getGradeClass(grade, isWeapon = false) {
        if (isWeapon) {
            // 法器品级
            if (grade === '法器') return 'grade-faqi';
            if (grade === '灵器') return 'grade-lingqi';
            if (grade === '灵宝') return 'grade-lingbao';
            if (grade === '法宝') return 'grade-fabao';
            if (grade === '仙器') return 'grade-xianqi';
            return 'grade-lingqi';
        } else {
            // 1-9品
            if (grade >= 1 && grade <= 3) return 'grade-1';
            if (grade >= 4 && grade <= 6) return 'grade-4';
            if (grade >= 7 && grade <= 9) return 'grade-7';
            return 'grade-1';
        }
    }

    // 辅助函数：品级显示文本
    function getGradeText(grade, isWeapon = false) {
        if (isWeapon) {
            return grade;
        } else {
            const gradeNames = ['', '一品', '二品', '三品', '四品', '五品', '六品', '七品', '八品', '九品'];
            return gradeNames[grade] || `${grade}品`;
        }
    }

    // 生成各类道具的HTML
    const categories = [
        { key: '灵资', name: '灵资', icon: '💊', color: '#22c55e' },
        { key: '法器', name: '法器', icon: '⚔️', color: '#8b5cf6' },
        { key: '杂物', name: '杂物', icon: '📦', color: '#9ca3af' },
        { key: '功法', name: '功法', icon: '📜', color: '#f59e0b' },
        { key: '法术', name: '法术', icon: '✨', color: '#ec4899' }
    ];

    let totalCount = 0;
    let tabsHtml = '';
    let panelsHtml = '';
    let firstTab = true;

    categories.forEach(category => {
        const categoryData = itemsData[category.key] || {};
        const itemKeys = Object.keys(categoryData).filter(k => k !== '$meta' && categoryData[k] !== null);
        const itemCount = itemKeys.length;
        totalCount += itemCount;

        // 生成Tab
        tabsHtml += `
            <div class="item-tab ${firstTab ? 'active' : ''}" data-item-tab="${category.key}">
                ${category.icon} ${category.name} (${itemCount})
    </div>
    `;

        // 生成面板内容
        let itemsHtml = '';

        if (itemCount === 0) {
            itemsHtml = `
                <div style="padding: 40px 20px; text-align: center; color: #9ca3af;">
                    <div style="font-size: 48px; margin-bottom: 12px; opacity: 0.3;">${category.icon}</div>
                    <div style="font-size: 14px;">暂无${category.name}</div>
        </div>
        `;
        } else {
            const isWeaponCategory = category.key === '法器';

            itemsHtml = '<div class="item-grid">' + itemKeys.map(key => {
                const item = categoryData[key];
                const name = item.名称?.[0] || key;
                const daotong = item.道统?.[0] || '';
                const grade = item.品级?.[0] || (isWeaponCategory ? '法器' : 1);
                const count = item.数量?.[0] || 1;

                const gradeClass = getGradeClass(grade, isWeaponCategory);
                const gradeText = getGradeText(grade, isWeaponCategory);

                let contentHtml = '';

                if (category.key === '灵资') {
                    const effect = item.效果?.[0] || '';
                    contentHtml = `
                        ${effect ? `<div class="item-description">${effect}</div>` : ''}
                    `;
                } else if (category.key === '法器') {
                    const isBenming = item.是否本命?.[0] || false;
                    const action = item.作用?.[0] || '';
                    const powerBoost = item.战力提升?.[0] || 0;
                    contentHtml = `
                        ${isBenming ? `<div class="item-benming">本命</div>` : ''}
                        ${action ? `<div class="item-description">${action}</div>` : ''}
                        ${powerBoost > 0 ? `<div class="item-power">⚡ 战力+${powerBoost}%</div>` : ''}
                        <button class="equip-fabao-btn" data-fabao-key="${key}" data-fabao-name="${name}">
                            <span class="btn-icon">⚔️</span>
                            <span>装备</span>
                        </button>
                    `;
                } else if (category.key === '杂物') {
                    const desc = item.说明?.[0] || '';
                    contentHtml = `
                        ${desc ? `<div class="item-description">${desc}</div>` : ''}
                    `;
                } else if (category.key === '功法') {
                    const effect = item.效果?.[0] || '';
                    contentHtml = `
                        ${effect ? `<div class="item-description">${effect}</div>` : ''}
                    `;
                } else if (category.key === '法术') {
                    const power = item.威力?.[0] || 0;
                    const consume = item.法力消耗?.[0] || 0;
                    const desc = item.描述?.[0] || '';
                    contentHtml = `
                        <div class="item-power">⚡ 威力${power} | 💧耗${consume}</div>
                        ${desc ? `<div class="item-description">${desc}</div>` : ''}
                    `;
                }

        return `
        <div class="item-card">
            <div class="item-header">
                        <div class="item-name">${name}</div>
                        ${count > 1 || category.key === '灵资' || category.key === '杂物' ? `<div class="item-count">×${count}</div>` : ''}
            </div>

                    <div class="item-meta">
                        ${daotong ? `<div class="item-daotong">${daotong}系</div>` : ''}
                        <div class="item-grade ${gradeClass}">${gradeText}</div>
            </div>

                    ${contentHtml}
    </div>
    `;
            }).join('') + '</div>';
        }

        panelsHtml += `
            <div class="item-panel ${firstTab ? 'active' : ''}" data-item-panel="${category.key}">
                ${itemsHtml}
        </div>
        `;

        firstTab = false;
    });

        return `
        <div class="section">
        <div class="section-title">🎁 道具仓库 (共${totalCount}项)</div>
            <div class="section-content">
            <!-- 道具分类标签 -->
            <div class="item-tabs">
                ${tabsHtml}
                    </div>

            <!-- 道具面板 -->
            ${panelsHtml}
        </div>
    </div>
    `;
}

// ========== 生成拍卖行 ==========
function generateAuctionHouse(auctionData, lingshi) {
    if (!auctionData) {
        return `
        <div class="section">
            <div class="section-title">🏛️ 拍卖行</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">暂无拍卖行数据</div>
            </div>
        </div>
        `;
    }

    // 辅助函数：获取品级颜色class
    function getGradeClass(grade, isWeapon = false) {
        if (isWeapon) {
            if (grade === '法器') return 'grade-faqi';
            if (grade === '灵器') return 'grade-lingqi';
            if (grade === '灵宝') return 'grade-lingbao';
            if (grade === '法宝') return 'grade-fabao';
            if (grade === '仙器') return 'grade-xianqi';
            return 'grade-lingqi';
        } else {
            if (grade >= 1 && grade <= 3) return 'grade-1';
            if (grade >= 4 && grade <= 6) return 'grade-4';
            if (grade >= 7 && grade <= 9) return 'grade-7';
            return 'grade-1';
        }
    }

    function getGradeText(grade, isWeapon = false) {
        if (isWeapon) {
            return grade;
        } else {
            const gradeNames = ['', '一品', '二品', '三品', '四品', '五品', '六品', '七品', '八品', '九品'];
            return gradeNames[grade] || `${grade}品`;
        }
    }

    const categories = [
        { key: '灵资', name: '灵资', icon: '💊', color: '#22c55e' },
        { key: '法器', name: '法器', icon: '⚔️', color: '#8b5cf6' },
        { key: '杂物', name: '杂物', icon: '📦', color: '#9ca3af' },
        { key: '功法', name: '功法', icon: '📜', color: '#f59e0b' },
        { key: '法术', name: '法术', icon: '✨', color: '#ec4899' }
    ];

    let totalCount = 0;
    let tabsHtml = '';
    let panelsHtml = '';
    let firstTab = true;

    categories.forEach(category => {
        const categoryData = auctionData[category.key] || {};
        const itemKeys = Object.keys(categoryData).filter(k => k !== '$meta' && categoryData[k] !== null);
        const itemCount = itemKeys.length;
        totalCount += itemCount;

        tabsHtml += `
            <div class="item-tab ${firstTab ? 'active' : ''}" data-item-tab="auction-${category.key}">
                ${category.icon} ${category.name} (${itemCount})
            </div>
        `;

        let itemsHtml = '';

        if (itemCount === 0) {
            itemsHtml = `
                <div style="padding: 40px 20px; text-align: center; color: #9ca3af;">
                    <div style="font-size: 48px; margin-bottom: 12px; opacity: 0.3;">${category.icon}</div>
                    <div style="font-size: 14px;">暂无${category.name}</div>
                </div>
            `;
        } else {
            const isWeaponCategory = category.key === '法器';

            itemsHtml = '<div class="item-grid">' + itemKeys.map(key => {
                const item = categoryData[key];
                const name = item.名称?.[0] || key;
                const daotong = item.道统?.[0] || '';
                const grade = item.品级?.[0] || (isWeaponCategory ? '法器' : 1);
                const count = item.数量?.[0] || 1;
                const price = item.价格?.[0] || 0;

                const gradeClass = getGradeClass(grade, isWeaponCategory);
                const gradeText = getGradeText(grade, isWeaponCategory);

                // 判断是否有足够的灵石购买
                const canBuy = lingshi >= price;

                let contentHtml = '';

                if (category.key === '灵资') {
                    const effect = item.效果?.[0] || '';
                    contentHtml = `
                        ${effect ? `<div class="item-description">${effect}</div>` : ''}
                    `;
                } else if (category.key === '法器') {
                    const isBenming = item.是否本命?.[0] || false;
                    const action = item.作用?.[0] || '';
                    const powerBoost = item.战力提升?.[0] || 0;
                    contentHtml = `
                        ${isBenming ? `<div class="item-benming">本命</div>` : ''}
                        ${action ? `<div class="item-description">${action}</div>` : ''}
                        ${powerBoost > 0 ? `<div class="item-power">⚡ 战力+${powerBoost}%</div>` : ''}
                    `;
                } else if (category.key === '杂物') {
                    const desc = item.说明?.[0] || '';
                    contentHtml = `
                        ${desc ? `<div class="item-description">${desc}</div>` : ''}
                    `;
                } else if (category.key === '功法') {
                    const effect = item.效果?.[0] || '';
                    contentHtml = `
                        ${effect ? `<div class="item-description">${effect}</div>` : ''}
                    `;
                } else if (category.key === '法术') {
                    const power = item.威力?.[0] || 0;
                    const consume = item.法力消耗?.[0] || 0;
                    const desc = item.描述?.[0] || '';
                    contentHtml = `
                        <div class="item-power">⚡ 威力${power} | 💧耗${consume}</div>
                        ${desc ? `<div class="item-description">${desc}</div>` : ''}
                    `;
                }

                return `
                <div class="item-card">
                    <div class="item-header">
                        <div class="item-name">${name}</div>
                        ${count > 1 || category.key === '灵资' || category.key === '杂物' ? `<div class="item-count">×${count}</div>` : ''}
                    </div>

                    <div class="item-meta">
                        ${daotong ? `<div class="item-daotong">${daotong}系</div>` : ''}
                        <div class="item-grade ${gradeClass}">${gradeText}</div>
                    </div>

                    ${contentHtml}

                    <div class="item-price" style="margin-top: 8px; padding: 8px; background: rgba(251, 191, 36, 0.1); border-radius: 6px; text-align: center; color: #fbbf24; font-weight: 600;">
                        💰 ${price} 灵石
                    </div>

                    <button class="buy-item-btn ${!canBuy ? 'disabled' : ''}" data-item-key="${key}" data-item-name="${name}" data-item-price="${price}" data-item-category="${category.key}" ${!canBuy ? 'disabled' : ''}>
                        <span class="btn-icon">💰</span>
                        <span>${canBuy ? '购买' : '灵石不足'}</span>
                    </button>
                </div>
                `;
            }).join('') + '</div>';
        }

        panelsHtml += `
            <div class="item-panel ${firstTab ? 'active' : ''}" data-item-panel="auction-${category.key}">
                ${itemsHtml}
            </div>
        `;

        firstTab = false;
    });

    return `
        <div class="section">
            <div class="section-title">🏛️ 拍卖行 (共${totalCount}项) | 💰 ${lingshi} 灵石</div>
            <div class="section-content">
                <!-- 我要拍卖按钮 -->
                <div style="margin-bottom: 12px; text-align: center;">
                    <button id="my-auction-btn" style="padding: 10px 20px; background: linear-gradient(135deg, rgba(251, 191, 36, 0.2) 0%, rgba(245, 158, 11, 0.2) 100%); border: 1px solid rgba(251, 191, 36, 0.5); border-radius: 8px; color: #fbbf24; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.3s;">
                        📦 我要拍卖
                    </button>
                </div>

                <!-- 拍卖行分类标签 -->
                <div class="item-tabs">
                    ${tabsHtml}
                </div>

                <!-- 拍卖行面板 -->
                ${panelsHtml}
            </div>
        </div>
    `;
}

// ========== 生成家族成员 ==========
function generateCharacterBonds(bonds, myPower) {
    const characters = Object.keys(bonds).filter(k => k !== '$meta' && bonds[k] !== null);

    if (characters.length === 0) {
        return `
        <div class="section">
            <div class="section-title">💖 家族成员</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">
                    暂无家族成员记录
                </div>
            </div>
        </div>
        `;
    }

    const charactersHtml = characters.map(charKey => {
        const character = bonds[charKey];
        const name = character.基础信息?.姓名?.[0] || charKey;
        const age = character.基础信息?.年龄?.[0] || '-';
        const identity = character.基础信息?.身份?.[0] || '-';
        const heartbeat = character.心跳?.[0] || 80;
        const favorability = character.好感度?.[0] || 0;
        const thought = character.心理状态?.当前所想?.[0] || '';

        // 修炼信息
        const cultivation = character.修炼信息 || {};
        const realm = cultivation.境界?.[0] || '未知';
        const realmDetail = cultivation.境界详情?.[0] || '';

        // 自动计算战斗力（读取AI填写的各项威力值，自动计算总战力）
        const combatPower = calculateCultivatorPower(cultivation);

        const daotong = cultivation.道统?.[0] || '-';
        const lingqiao = cultivation.灵窍 || {};
        const lingqiaoPos = lingqiao.位置?.[0] || '-';
        const lingqiaoQuality = lingqiao.品质?.[0] || '-';

        // 天赋
        const talents = safeGetArray(cultivation.天赋?.[0]);

        // 法力和体力
        const fali = cultivation.法力值?.[0] || 0;
        const faliMax = cultivation.法力上限?.[0] || 1;
        const tili = cultivation.体力值?.[0] || 0;
        const tiliMax = cultivation.体力上限?.[0] || 1;

        // 仙基（筑基境专用，只有1道）
        const xianjiInfo = cultivation.仙基 || {};
        const xianjiName = xianjiInfo.名称?.[0] || '';
        const xianjiGrade = xianjiInfo.品级?.[0] || '';
        const xianjiSkill = xianjiInfo.熟练度?.[0] || '';
        const xianjiPower = xianjiInfo.威力?.[0] || 0;
        const xianjiDesc = xianjiInfo.描述?.[0] || '';

        // 判断是否为筑基境（只显示仙基）还是紫府以上（显示神通）
        const isZhuji = realm.includes('筑基');

        // 神通（紫府境及以上才有，1-5道）
        const shentongData = cultivation.神通 || {};
        const shentongKeys = Object.keys(shentongData).filter(k => k !== '$meta');
        let shentongHtml = '';
        if (!isZhuji && shentongKeys.length > 0) {
            shentongHtml = shentongKeys.map(stKey => {
                const st = shentongData[stKey];
                const stGrade = st.品级?.[0] || '';
                const stSkill = st.熟练度?.[0] || '';
                const stPower = st.威力?.[0] || 0;
                const stDesc = st.描述?.[0] || '';
                return `<div style="font-size: 14px; padding: 4px 8px; background: rgba(212, 165, 116, 0.2); border-radius: 4px; margin-bottom: 4px; border: 1px solid #d4a574;">
                    <span style="color: #8b6914; font-weight: 700;">${stKey}</span> 
                    <span style="color: #8b7355; font-weight: 500;">(${stGrade} ${stSkill})</span>
                    <span style="color: #fbbf24; margin-left: 4px;">威力${stPower}</span>
                    ${stDesc ? `<br><span style="color: #333; font-size: 14px;">${stDesc}</span>` : ''}
                </div>`;
            }).join('');
        }

        // 筑基的仙基显示（筑基只修1道仙基）
        let xianjiHtml = '';
        if (isZhuji && xianjiName) {
            xianjiHtml = `<div style="font-size: 14px; padding: 4px 8px; background: rgba(139, 92, 246, 0.1); border-radius: 4px; margin-bottom: 4px;">
                <span style="color: #a78bfa; font-weight: 600;">${xianjiName}</span> 
                <span style="color: #9ca3af;">(${xianjiGrade} ${xianjiSkill})</span>
                <span style="color: #fbbf24; margin-left: 4px;">威力${xianjiPower}</span>
                ${xianjiDesc ? `<br><span style="color: #333; font-size: 14px;">${xianjiDesc}</span>` : ''}
            </div>`;
        }

        // 金性
        const jinxing = cultivation.金性 || {};
        const jinxingType = jinxing.类型?.[0] || '';
        const jinxingDaotong = jinxing.道统?.[0] || '';
        const jinxingShuangquan = jinxing.性命双全?.[0] || false;

        // 太虚运用
        const taixu = cultivation.太虚运用?.[0] || '';

        // 外貌信息
        const appearance = character.基础信息?.外貌 || {};
        const height = appearance.身高?.[0] || '-';
        const hairColor = appearance.发色?.[0] || '-';
        const hairStyle = appearance.发型?.[0] || '-';
        const eyeColor = appearance.瞳色?.[0] || '-';
        const skinColor = appearance.肤色?.[0] || '-';
        const bodyType = appearance.体型?.[0] || '-';

        // 服装信息
        const clothing = character.服装 || {};
        const top = clothing.上衣?.[0] || '-';
        const bottom = clothing.下装?.[0] || '-';
        const underwear = clothing.内衣?.[0] || '-';
        const panties = clothing.内裤?.[0] || '-';
        const stockings = clothing.丝袜?.[0] || '';
        const shoes = clothing.鞋子?.[0] || '-';

        // 身体特征
        const bodyFeatures = character.身体特征 || {};
        const bodyShape = bodyFeatures.身形?.[0] || '-';
        const specialMarks = safeGetArray(bodyFeatures.特殊标记?.[0]);

        // 法宝灵器
        const fabaoData = character.法宝灵器 || {};
        const fabaoKeys = Object.keys(fabaoData).filter(k => k !== '$meta');
        let fabaoHtml = '';
        if (fabaoKeys.length > 0) {
            fabaoHtml = fabaoKeys.map(fbKey => {
                const fb = fabaoData[fbKey];
                const fbName = fb.名称?.[0] || fbKey;
                const fbGrade = fb.品级?.[0] || '';
                const fbDaotong = fb.道统?.[0] || '';
                const fbBenming = fb.是否本命?.[0] || false;
                const fbFunc = fb.功能?.[0] || '';
                return `<div style="font-size: 14px; padding: 4px 8px; background: rgba(139, 92, 246, 0.1); border-radius: 4px; margin-bottom: 4px;">
                    <span style="color: #8b5cf6; font-weight: 600;">${fbName}</span> 
                    <span style="color: #9ca3af;">(${fbGrade}${fbBenming ? ' 本命' : ''})</span>
                    ${fbDaotong ? `<span style="color: #60a5fa; margin-left: 4px;">${fbDaotong}系</span>` : ''}
                    ${fbFunc ? `<br><span style="color: rgba(0,0,0,0.7); font-size: 14px;">${fbFunc}</span>` : ''}
                </div>`;
            }).join('');
        }

        // 灵资丹药
        const lingziData = character.灵资丹药 || {};
        const lingziKeys = Object.keys(lingziData).filter(k => k !== '$meta');
        let lingziHtml = '';
        if (lingziKeys.length > 0) {
            lingziHtml = lingziKeys.map(lzKey => {
