        // 关系信息
        const relationInfo = character.关系信息 || {};
        const daolu = relationInfo.道侣?.[0] || '';
        const children = safeGetArray(relationInfo.子女?.[0]);
        const memories = safeGetArray(relationInfo.人物记忆?.[0]);

        return `
