                </svg>
                    <span>${heartbeat} BPM</span>
                </div>
                <span style="color: ${favorability >= 80 ? '#ff6b81' : favorability >= 50 ? '#4ade80' : favorability >= 20 ? '#60a5fa' : favorability >= 0 ? '#9ca3af' : favorability >= -50 ? '#fb923c' : '#ef4444'};">
                    ${favorability >= 80 ? '💗' : favorability >= 50 ? '💚' : favorability >= 20 ? '💙' : favorability >= 0 ? '🤝' : favorability >= -50 ? '😠' : '💢'} ${favorability}
                </span>
                <span style="color: #9ca3af;">| ${identity}</span>
            </div>

            <!-- 交互按钮 -->
            <div style="margin-top: 8px; margin-bottom: 8px; display: flex; gap: 6px; flex-wrap: wrap;">
                <button class="member-chat-btn" data-character="${charKey}" data-character-name="${name}" style="flex: 1; padding: 6px 12px; background: linear-gradient(135deg, rgba(96, 165, 250, 0.2) 0%, rgba(59, 130, 246, 0.2) 100%); border: 1px solid rgba(96, 165, 250, 0.5); border-radius: 6px; color: #60a5fa; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.3s;">
