                    <div><span style="color: #9ca3af;">灵窍:</span> ${lingqiaoPos} (${lingqiaoQuality})</div>
                    ${jinxingType ? `<div><span style="color: #9ca3af;">金性:</span> <span style="color: #fbbf24;">${jinxingDaotong}${jinxingType}</span> ${jinxingShuangquan ? '✓性命双全' : ''}</div>` : ''}
                    ${taixu ? `<div><span style="color: #9ca3af;">太虚:</span> ${taixu}</div>` : ''}
                </div>

                <!-- 天赋 -->
                ${talents.length > 0 ? `
                <div style="margin-top: 8px;">
                    <div style="color: #000; font-size: 14px; margin-bottom: 4px;">✨ 天赋</div>
                    <div style="display: flex; flex-wrap: wrap; gap: 4px;">
                        ${talents.map(talent => `
                            <div style="padding: 2px 6px; background: rgba(251, 191, 36, 0.15); border: 1px solid rgba(251, 191, 36, 0.3); border-radius: 3px; color: #fbbf24; font-size: 14px; font-weight: 600;">
                                ${talent}
                            </div>
                        `).join('')}
                    </div>
                </div>
                ` : ''}

                <!-- 法力和体力 -->
                <div style="margin-top: 8px; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
                    <div style="padding: 6px; background: rgba(212, 165, 116, 0.2); border-radius: 4px; text-align: center; border: 1px solid #d4a574;">
                        <div style="color: #8b7355; font-size: 14px; margin-bottom: 2px;">法力</div>
                        <div style="color: #8b6914; font-size: 14px; font-weight: 700;">${fali}/${faliMax}</div>
                        <div style="height: 4px; background: rgba(0,0,0,0.3); border-radius: 2px; margin-top: 4px; overflow: hidden;">
                            <div style="height: 100%; background: linear-gradient(90deg, #4a9eff, #64b5f6); width: ${(fali/faliMax*100).toFixed(0)}%; transition: width 0.3s;"></div>
                </div>
                    </div>
                    <div style="padding: 6px; background: rgba(34, 197, 94, 0.1); border-radius: 4px; text-align: center; border: 1px solid rgba(34, 197, 94, 0.3);">
                        <div style="color: #8b7355; font-size: 14px; margin-bottom: 2px;">体力</div>
                        <div style="color: #22c55e; font-size: 14px; font-weight: 700;">${tili}/${tiliMax}</div>
                        <div style="height: 4px; background: rgba(0,0,0,0.3); border-radius: 2px; margin-top: 4px; overflow: hidden;">
                            <div style="height: 100%; background: linear-gradient(90deg, #22c55e, #4ade80); width: ${(tili/tiliMax*100).toFixed(0)}%; transition: width 0.3s;"></div>
                        </div>
                    </div>
                </div>

                <div style="margin-top: 8px; text-align: center; padding: 6px; background: rgba(255, 107, 129, 0.1); border-radius: 4px;">
                    <span style="color: #ff6b81; font-size: 14px; font-weight: 600;">战斗力: ${combatPower.toFixed(1)}</span>${powerComparison}
                </div>
            </div>

            <!-- 仙基（筑基境专用，只有1道） -->
            ${xianjiHtml ? `
            <div style="margin-top: 10px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">🔮 仙基（突破紫府时化为神通）</div>
                ${xianjiHtml}
            </div>
            ` : ''}

            <!-- 神通（紫府境及以上，1-5道） -->
            ${shentongHtml ? `
            <div style="margin-top: 10px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">✨ 神通 (${shentongKeys.length}/5道)</div>
                ${shentongHtml}
            </div>
            ` : ''}

            <!-- 法宝灵器 -->
            ${fabaoHtml ? `
            <div style="margin-top: 10px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">🗡️ 法宝灵器 (${fabaoKeys.length}件)</div>
                ${fabaoHtml}
            </div>
            ` : ''}

            <!-- 灵资丹药 -->
            ${lingziHtml ? `
            <div style="margin-top: 10px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">💊 灵资丹药 (${lingziKeys.length}种)</div>
                ${lingziHtml}
            </div>
            ` : ''}

            <!-- 外貌特征 -->
            <div style="margin-top: 10px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">外貌特征</div>
                <div class="bond-stats">
                    <div><span style="color: #9ca3af;">身高:</span> ${height}</div>
                    <div><span style="color: #9ca3af;">身形:</span> ${bodyShape}</div>
                    <div><span style="color: #9ca3af;">发色:</span> ${hairColor}</div>
                    <div><span style="color: #9ca3af;">发型:</span> ${hairStyle}</div>
                    <div><span style="color: #9ca3af;">瞳色:</span> ${eyeColor}</div>
                    <div><span style="color: #9ca3af;">肤色:</span> ${skinColor}</div>
                    ${specialMarks.length > 0 ? `<div style="grid-column: 1 / -1; font-size: 14px;"><span style="color: #9ca3af;">特殊标记:</span> ${specialMarks.join('; ')}</div>` : ''}
                </div>
            </div>

            <!-- 当前着装 -->
            <div style="margin-top: 10px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">当前着装</div>
                <div class="bond-stats">
                    ${top !== '-' ? `<div style="font-size: 14px;"><span style="color: #9ca3af;">上衣:</span> ${top}</div>` : ''}
                    ${bottom !== '-' ? `<div style="font-size: 14px;"><span style="color: #9ca3af;">下装:</span> ${bottom}</div>` : ''}
                    ${underwear !== '-' ? `<div style="font-size: 14px;"><span style="color: #9ca3af;">内衣:</span> ${underwear}</div>` : ''}
                    ${panties !== '-' ? `<div style="font-size: 14px;"><span style="color: #9ca3af;">内裤:</span> ${panties}</div>` : ''}
                    ${stockings ? `<div style="font-size: 14px;"><span style="color: #9ca3af;">丝袜:</span> ${stockings}</div>` : ''}
                    ${shoes !== '-' ? `<div style="font-size: 14px;"><span style="color: #9ca3af;">鞋子:</span> ${shoes}</div>` : ''}
                </div>
            </div>

            <!-- 人物记忆 -->
            ${memories.length > 0 ? `
            <div style="margin-top: 10px;">
                <div style="color: #000; font-size: 14px; margin-bottom: 6px;">📝 人物记忆</div>
                <div style="display: flex; flex-direction: column; gap: 6px;">
                    ${memories.map(memory => `
                        <div style="font-size: 14px; padding: 6px 10px; background: rgba(255, 255, 255, 0.05); border-radius: 4px; border-left: 3px solid rgba(255, 107, 129, 0.5);">
                            ${memory}
                        </div>
                    `).join('')}
                </div>
            </div>
            ` : ''}
            </div><!-- 关闭 bond-details -->
        </div>
        `;
    }).join('');

    return `
    <div class="section">
        <div class="section-title">💖 家族成员 (${characters.length}人)</div>
        <div class="section-content">
            <div class="bond-list">
                ${charactersHtml}
            </div>
        </div>
    </div>
    `;
}

// ========== 生成当前目标 ==========
function generateCurrentTargets(targets, myPower) {
    const characters = Object.keys(targets).filter(k => k !== '$meta' && targets[k] !== null);

    if (characters.length === 0) {
        return `
        <div class="section">
            <div class="section-title">🎯 当前目标</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">
                    暂无目标记录
                </div>
            </div>
        </div>
        `;
    }

    const charactersHtml = characters.map(charKey => {
        const character = targets[charKey];
        const name = character.基础信息?.姓名?.[0] || charKey;
        const age = character.基础信息?.年龄?.[0] || '-';
        const identity = character.基础信息?.身份?.[0] || '-';
        const heartbeat = character.心跳?.[0] || 80;
        const favorability = character.好感度?.[0] || 0;

        // 修炼信息
        const cultivation = character.修炼信息 || {};
        const realm = cultivation.境界?.[0] || '未知';
        const realmDetail = cultivation.境界详情?.[0] || '';

        // 自动计算战斗力（读取AI填写的各项威力值，自动计算总战力）
        const combatPower = calculateCultivatorPower(cultivation);

        const daotong = cultivation.道统?.[0] || '-';

        // 天赋
        const talents = safeGetArray(cultivation.天赋?.[0]);

        // 法力和体力
        const fali = cultivation.法力值?.[0] || 0;
        const faliMax = cultivation.法力上限?.[0] || 1;
        const tili = cultivation.体力值?.[0] || 0;
        const tiliMax = cultivation.体力上限?.[0] || 1;

        // 仙基（筑基境专用，只有1道）
        const xianjiInfo = cultivation.仙基 || {};
        const xianjiName = xianjiInfo.名称?.[0] || '';
        const xianjiGrade = xianjiInfo.品级?.[0] || '';
        const xianjiSkill = xianjiInfo.熟练度?.[0] || '';
        const xianjiPower = xianjiInfo.威力?.[0] || 0;
        const xianjiDesc = xianjiInfo.描述?.[0] || '';

        // 判断是否为筑基境（只显示仙基）还是紫府以上（显示神通）
        const isZhuji = realm.includes('筑基');

        // 神通（紫府境及以上才有，1-5道）
        const shentongData = cultivation.神通 || {};
        const shentongKeys = Object.keys(shentongData).filter(k => k !== '$meta');
        let shentongHtml = '';
        if (!isZhuji && shentongKeys.length > 0) {
            shentongHtml = shentongKeys.map(stKey => {
                const st = shentongData[stKey];
                const stGrade = st.品级?.[0] || '';
                const stSkill = st.熟练度?.[0] || '';
                const stPower = st.威力?.[0] || 0;
                const stDesc = st.描述?.[0] || '';
                return `<div style="font-size: 14px; padding: 4px 8px; background: rgba(212, 165, 116, 0.2); border-radius: 4px; margin-bottom: 4px; border: 1px solid #d4a574;">
                    <span style="color: #8b6914; font-weight: 700;">${stKey}</span> 
                    <span style="color: #8b7355; font-weight: 500;">(${stGrade} ${stSkill})</span>
                    <span style="color: #fbbf24; margin-left: 4px;">威力${stPower}</span>
                    ${stDesc ? `<br><span style="color: rgba(0,0,0,0.7); font-size: 14px;">${stDesc}</span>` : ''}
                </div>`;
            }).join('');
        }

        // 筑基的仙基显示（筑基只修1道仙基）
        let xianjiHtml = '';
        if (isZhuji && xianjiName) {
            xianjiHtml = `<div style="font-size: 14px; padding: 4px 8px; background: rgba(139, 92, 246, 0.1); border-radius: 4px; margin-bottom: 4px;">
                <span style="color: #a78bfa; font-weight: 600;">${xianjiName}</span> 
                <span style="color: #9ca3af;">(${xianjiGrade} ${xianjiSkill})</span>
                <span style="color: #fbbf24; margin-left: 4px;">威力${xianjiPower}</span>
                ${xianjiDesc ? `<br><span style="color: rgba(0,0,0,0.7); font-size: 14px;">${xianjiDesc}</span>` : ''}
            </div>`;
        }

        // 金性
        const jinxing = cultivation.金性 || {};
        const jinxingType = jinxing.类型?.[0] || '';
        const jinxingDaotong = jinxing.道统?.[0] || '';
        const jinxingShuangquan = jinxing.性命双全?.[0] || false;

        // 太虚运用
        const taixu = cultivation.太虚运用?.[0] || '';

        // 外貌信息
        const appearance = character.基础信息?.外貌 || {};
        const height = appearance.身高?.[0] || '-';
        const hairColor = appearance.发色?.[0] || '-';
        const hairStyle = appearance.发型?.[0] || '-';
        const eyeColor = appearance.瞳色?.[0] || '-';
        const skinColor = appearance.肤色?.[0] || '-';
        const bodyType = appearance.体型?.[0] || '-';

        // 身体特征
        const bodyFeatures = character.身体特征 || {};
        const bodyShape = bodyFeatures.身形?.[0] || '-';
        const specialMarks = safeGetArray(bodyFeatures.特殊标记?.[0]);

        // 法宝灵器
        const fabaoData = character.法宝灵器 || {};
        const fabaoKeys = Object.keys(fabaoData).filter(k => k !== '$meta');
        let fabaoHtml = '';
        if (fabaoKeys.length > 0) {
            fabaoHtml = fabaoKeys.map(fbKey => {
                const fb = fabaoData[fbKey];
                const fbName = fb.名称?.[0] || fbKey;
                const fbGrade = fb.品级?.[0] || '';
                const fbDaotong = fb.道统?.[0] || '';
                const fbBenming = fb.是否本命?.[0] || false;
                const fbFunc = fb.功能?.[0] || '';
                return `<div style="font-size: 14px; padding: 4px 8px; background: rgba(139, 92, 246, 0.1); border-radius: 4px; margin-bottom: 4px;">
                    <span style="color: #8b5cf6; font-weight: 600;">${fbName}</span> 
                    <span style="color: #9ca3af;">(${fbGrade}${fbBenming ? ' 本命' : ''})</span>
                    ${fbDaotong ? `<span style="color: #60a5fa; margin-left: 4px;">${fbDaotong}系</span>` : ''}
                    ${fbFunc ? `<br><span style="color: rgba(0,0,0,0.7); font-size: 14px;">${fbFunc}</span>` : ''}
                </div>`;
            }).join('');
        }

        // 灵资丹药
        const lingziData = character.灵资丹药 || {};
        const lingziKeys = Object.keys(lingziData).filter(k => k !== '$meta');
        let lingziHtml = '';
        if (lingziKeys.length > 0) {
            lingziHtml = lingziKeys.map(lzKey => {
                const lz = lingziData[lzKey];
                const lzName = lz.名称?.[0] || lzKey;
                const lzCount = lz.数量?.[0] || 0;
                const lzUse = lz.用途?.[0] || '';
                return `<div style="font-size: 14px; padding: 4px 8px; background: rgba(34, 197, 94, 0.1); border-radius: 4px; margin-bottom: 4px;">
                    <span style="color: #22c55e; font-weight: 600;">${lzName}</span> 
                    <span style="color: #fbbf24;">×${lzCount}</span>
                    ${lzUse ? `<br><span style="color: rgba(0,0,0,0.7); font-size: 14px;">${lzUse}</span>` : ''}
                </div>`;
            }).join('');
        }

        // 计算心电图动画速度
        const animationDuration = ((60000 / heartbeat) * 2).toFixed(0);

        // 根据战斗力绝对值评价档位（符合修炼境界递进）
        // 凡人~胎息:10以下 胎息中后:10-100 筑基前:100-500 筑基中:500-1500 筑基后:1500-5000 紫府初中:5000-15000 紫府后:15000-30000 紫府巅峰:30000+
        let powerComparison = '';
        if (combatPower > 0) {
            let ratingText = '';
            let ratingColor = '';
            if (combatPower >= 30000) {
                ratingText = '通天彻地';
                ratingColor = '#f472b6';
            } else if (combatPower >= 15000) {
                ratingText = '天赋异禀';
                ratingColor = '#c084fc';
            } else if (combatPower >= 5000) {
                ratingText = '出类拔萃';
                ratingColor = '#a78bfa';
            } else if (combatPower >= 1500) {
                ratingText = '实力强横';
                ratingColor = '#8b5cf6';
            } else if (combatPower >= 500) {
                ratingText = '道行不凡';
                ratingColor = '#60a5fa';
            } else if (combatPower >= 100) {
                ratingText = '初窥大道';
                ratingColor = '#4ade80';
            } else if (combatPower >= 50) {
                ratingText = '小有所成';
                ratingColor = '#fbbf24';
            } else if (combatPower >= 10) {
                ratingText = '渐入佳境';
                ratingColor = '#fb923c';
            } else {
                ratingText = '初入修行';
                ratingColor = '#9ca3af';
            }
            powerComparison = `<span style="color: ${ratingColor}; font-weight: 600; margin-left: 8px;">${ratingText}</span>`;
        }

        return `
        <div class="bond-item collapsed" style="border-left-color: rgba(255, 193, 7, 0.5);">
            <div class="bond-name" style="color: #ffc107;">
                ${name} (${age}岁)
            </div>
            <div style="font-size: 14px; color: #9ca3af; margin-bottom: 8px; display: flex; align-items: center; gap: 8px; flex-wrap: wrap;">
                <div style="display: flex; align-items: center; gap: 8px;">
                <svg style="width: 40px; height: 20px;" viewBox="0 0 80 73" xmlns="http://www.w3.org/2000/svg">
                    <polyline style="fill: none; stroke: rgba(255, 193, 7, 0.2); stroke-width: 3; stroke-linecap: round; stroke-linejoin: round;" points="0 47.907, 28 47.907, 32 23.907, 36 59.907, 40 51.907, 44 47.907, 80 47.907"></polyline>
                    <polyline style="fill: none; stroke: #ffc107; stroke-width: 3; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 48, 144; stroke-dashoffset: 192; animation: heartbeat-dash-anim ${animationDuration}ms linear infinite;" points="0 47.907, 28 47.907, 32 23.907, 36 59.907, 40 51.907, 44 47.907, 80 47.907"></polyline>
                </svg>
                    <span>${heartbeat} BPM</span>
                </div>
                <span style="color: ${favorability >= 80 ? '#ff6b81' : favorability >= 50 ? '#4ade80' : favorability >= 20 ? '#60a5fa' : favorability >= 0 ? '#9ca3af' : favorability >= -50 ? '#fb923c' : '#ef4444'};">
                    ${favorability >= 80 ? '💗' : favorability >= 50 ? '💚' : favorability >= 20 ? '💙' : favorability >= 0 ? '🤝' : favorability >= -50 ? '😠' : '💢'} ${favorability}
                </span>
                <span style="color: #9ca3af;">| ${identity}</span>
            </div>

            <!-- 交互按钮 -->
            <div style="margin-top: 8px; margin-bottom: 8px; display: flex; gap: 6px; flex-wrap: wrap;">
                <button class="target-chat-btn" data-character="${charKey}" data-character-name="${name}" style="flex: 1; padding: 6px 12px; background: linear-gradient(135deg, rgba(96, 165, 250, 0.2) 0%, rgba(59, 130, 246, 0.2) 100%); border: 1px solid rgba(96, 165, 250, 0.5); border-radius: 6px; color: #60a5fa; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.3s;">
                     交谈
                </button>
                <button class="target-gift-btn" data-character="${charKey}" data-character-name="${name}" style="flex: 1; padding: 6px 12px; background: linear-gradient(135deg, rgba(251, 191, 36, 0.2) 0%, rgba(245, 158, 11, 0.2) 100%); border: 1px solid rgba(251, 191, 36, 0.5); border-radius: 6px; color: #fbbf24; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.3s;">
                     赠予
                </button>
                <button class="target-cultivate-btn" data-character="${charKey}" data-character-name="${name}" data-favorability="${favorability}" style="flex: 1; padding: 6px 12px; background: linear-gradient(135deg, rgba(236, 72, 153, 0.2) 0%, rgba(219, 39, 119, 0.2) 100%); border: 1px solid rgba(236, 72, 153, 0.5); border-radius: 6px; color: #ec4899; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.3s;">
                     双修
                </button>
                <button class="target-attack-btn" data-character="${charKey}" data-character-name="${name}" data-my-power="${myPower.toFixed(1)}" data-target-power="${combatPower.toFixed(1)}" style="flex: 1; padding: 6px 12px; background: linear-gradient(135deg, rgba(239, 68, 68, 0.2) 0%, rgba(220, 38, 38, 0.2) 100%); border: 1px solid rgba(239, 68, 68, 0.5); border-radius: 6px; color: #ef4444; font-size: 14px; font-weight: 600; cursor: pointer; transition: all 0.3s;">
                     攻击
                </button>
            </div>

            <!-- 详细信息（可折叠） -->
            <div class="bond-details">

            <!-- 修炼信息 -->
            <div style="margin-top: 10px;">
                <div style="color: #a0826d; font-size: 14px; margin-bottom: 6px;">⚔️ 修炼信息</div>
                <div class="bond-stats">
                    <div><span style="color: #a0826d;">境界:</span> ${realm}</div>
                    ${realmDetail ? `<div style="grid-column: 1 / -1; font-size: 14px;"><span style="color: #a0826d;">详情:</span> ${realmDetail}</div>` : ''}
                    <div><span style="color: #a0826d;">道统:</span> <span style="color: #d4a574;">${daotong}</span></div>
                    ${jinxingType ? `<div><span style="color: #a0826d;">金性:</span> <span style="color: #fbbf24;">${jinxingDaotong}${jinxingType}</span> ${jinxingShuangquan ? '✓性命双全' : ''}</div>` : ''}
                    ${taixu ? `<div><span style="color: #a0826d;">太虚:</span> ${taixu}</div>` : ''}
                </div>

                <!-- 天赋 -->
                ${talents.length > 0 ? `
                <div style="margin-top: 8px;">
                    <div style="color: #a0826d; font-size: 14px; margin-bottom: 4px;">✨ 天赋</div>
                    <div style="display: flex; flex-wrap: wrap; gap: 4px;">
                        ${talents.map(talent => `
                            <div style="padding: 2px 6px; background: rgba(251, 191, 36, 0.15); border: 1px solid rgba(251, 191, 36, 0.3); border-radius: 3px; color: #fbbf24; font-size: 14px; font-weight: 600;">
                                ${talent}
                            </div>
                        `).join('')}
                    </div>
                </div>
                ` : ''}

                <!-- 法力和体力 -->
                <div style="margin-top: 8px; display: grid; grid-template-columns: 1fr 1fr; gap: 8px;">
                    <div style="padding: 6px; background: rgba(212, 165, 116, 0.2); border-radius: 4px; text-align: center; border: 1px solid #d4a574;">
                        <div style="color: #8b7355; font-size: 14px; margin-bottom: 2px;">法力</div>
                        <div style="color: #8b6914; font-size: 14px; font-weight: 700;">${fali}/${faliMax}</div>
                        <div style="height: 4px; background: rgba(0,0,0,0.3); border-radius: 2px; margin-top: 4px; overflow: hidden;">
                            <div style="height: 100%; background: linear-gradient(90deg, #4a9eff, #64b5f6); width: ${(fali/faliMax*100).toFixed(0)}%; transition: width 0.3s;"></div>
                </div>
                    </div>
                    <div style="padding: 6px; background: rgba(34, 197, 94, 0.1); border-radius: 4px; text-align: center; border: 1px solid rgba(34, 197, 94, 0.3);">
                        <div style="color: #8b7355; font-size: 14px; margin-bottom: 2px;">体力</div>
                        <div style="color: #22c55e; font-size: 14px; font-weight: 700;">${tili}/${tiliMax}</div>
                        <div style="height: 4px; background: rgba(0,0,0,0.3); border-radius: 2px; margin-top: 4px; overflow: hidden;">
                            <div style="height: 100%; background: linear-gradient(90deg, #22c55e, #4ade80); width: ${(tili/tiliMax*100).toFixed(0)}%; transition: width 0.3s;"></div>
                        </div>
                    </div>
                </div>

                <div style="margin-top: 8px; text-align: center; padding: 6px; background: rgba(255, 193, 7, 0.1); border-radius: 4px;">
                    <span style="color: #ffc107; font-size: 14px; font-weight: 600;">战斗力: ${combatPower.toFixed(1)}</span>${powerComparison}
                </div>
            </div>

            <!-- 仙基（筑基境专用，只有1道） -->
            ${xianjiHtml ? `
            <div style="margin-top: 10px;">
                <div style="color: #a0826d; font-size: 14px; margin-bottom: 6px;">🔮 仙基（突破紫府时化为神通）</div>
                ${xianjiHtml}
            </div>
            ` : ''}

            <!-- 神通（紫府境及以上，1-5道） -->
            ${shentongHtml ? `
            <div style="margin-top: 10px;">
                <div style="color: #a0826d; font-size: 14px; margin-bottom: 6px;">✨ 神通 (${shentongKeys.length}/5道)</div>
                ${shentongHtml}
            </div>
            ` : ''}

            <!-- 法宝灵器 -->
            ${fabaoHtml ? `
            <div style="margin-top: 10px;">
                <div style="color: #a0826d; font-size: 14px; margin-bottom: 6px;">🗡️ 法宝灵器 (${fabaoKeys.length}件)</div>
                ${fabaoHtml}
            </div>
            ` : ''}

            <!-- 灵资丹药 -->
            ${lingziHtml ? `
