// ========== 建筑资源选择弹窗 ==========
function showBuildingResourceSelector(items, buildingName, needGrade, needCount, lingshiCost, isConstruct, onConfirm) {
    console.log('📋 显示建筑资源选择弹窗');

    let selectedItem = null;
    const actionText = isConstruct ? '建造' : '升级';

    // 创建弹窗HTML
    const modalHtml = `
        <div class="breakthrough-modal" id="building-resource-modal">
            <div class="breakthrough-modal-content">
                <div class="breakthrough-modal-header">
                    <div class="breakthrough-modal-title">
                        ${isConstruct ? '🔨' : '⬆️'} ${actionText}${buildingName}
                    </div>
                    <button class="breakthrough-modal-close" id="building-modal-close">×</button>
                </div>

                <div class="breakthrough-requirement">
                    <div class="breakthrough-requirement-title">${actionText}需要</div>
                    <div class="breakthrough-requirement-content">
                        💎 ${lingshiCost} 灵石 + 💊 ${needGrade}品及以上灵资 ×${needCount}
                    </div>
                </div>

                <div class="breakthrough-items-list" id="building-items-list">
                    ${items.map((item, index) => `
                        <div class="breakthrough-item" data-index="${index}">
                            <div class="breakthrough-item-header">
                                <div class="breakthrough-item-name">${item.name}</div>
                                <div class="breakthrough-item-count">拥有 ×${item.count}</div>
                            </div>
                            <div class="breakthrough-item-info">
                                <span>品级：${item.grade}品</span>
                                ${item.daotong ? `<span>道统：${item.daotong}</span>` : ''}
                            </div>
                            ${item.effect ? `<div style="font-size: 14px; color: #a0826d; margin-top: 4px;">${item.effect}</div>` : ''}
                        </div>
                    `).join('')}
                </div>

                <div class="breakthrough-modal-buttons">
                    <button class="breakthrough-modal-btn breakthrough-modal-btn-cancel" id="building-modal-cancel">取消</button>
                    <button class="breakthrough-modal-btn breakthrough-modal-btn-confirm" id="building-modal-confirm" disabled>确定${actionText}</button>
                </div>
            </div>
        </div>
    `;

    // 添加到页面
    $('body').append(modalHtml);

    const $modal = $('#building-resource-modal');
    const $itemsList = $('#building-items-list');
    const $confirmBtn = $('#building-modal-confirm');

    // 点击灵资项选择
    $itemsList.on('click', '.breakthrough-item', function() {
        const index = parseInt($(this).data('index'));
        selectedItem = items[index];

        $('.breakthrough-item').removeClass('selected');
        $(this).addClass('selected');

        $confirmBtn.prop('disabled', false);

        console.log('📦 选中灵资:', selectedItem);
    });

    // 确定按钮
    $confirmBtn.on('click', function() {
        if (selectedItem) {
            $modal.remove();
            onConfirm(selectedItem);
        }
    });

    // 取消按钮
    $('#building-modal-cancel, #building-modal-close').on('click', function() {
        $modal.remove();
    });

    // 点击背景关闭
    $modal.on('click', function(e) {
        if (e.target === this) {
            $modal.remove();
        }
    });
}

// ========== 执行建筑操作（建造/升级） ==========
async function performBuildingOperation(buildingKey, buildingName, isConstruct, selectedItem, targetMessageId, lingshiCost, lingziCount = 0) {
    console.log(`${isConstruct ? '🔨' : '⬆️'} 执行${isConstruct ? '建造' : '升级'}:`, buildingKey);

    try {
        const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

        if (!mvuData || !mvuData.stat_data) {
            toastr.error('操作失败：无法获取数据');
            return;
        }

        // 扣除灵石
        const currentLingshi = mvuData.stat_data['家族信息']?.['灵石']?.[0] || 0;
        const newLingshi = currentLingshi - lingshiCost;
        await Mvu.setMvuVariable(mvuData, `家族信息.灵石[0]`, newLingshi, { 
            reason: `${isConstruct ? '建造' : '升级'}建筑消耗灵石`, 
            is_recursive: false 
        });

        // 如果有选中的灵资，消耗它
        if (selectedItem && lingziCount > 0) {
            const newCount = selectedItem.count - lingziCount;

            if (newCount > 0) {
                // 减少数量
                await Mvu.setMvuVariable(mvuData, `道具.灵资.${selectedItem.key}.数量[0]`, newCount, { 
                    reason: `${isConstruct ? '建造' : '升级'}建筑消耗灵资`, 
                    is_recursive: false 
                });
                console.log(`✅ 消耗灵资: ${selectedItem.name} ×${lingziCount}, 剩余 ${newCount}`);
            } else {
                // 数量为0，删除该灵资
                await Mvu.setMvuVariable(mvuData, `道具.灵资.${selectedItem.key}`, null, { 
                    reason: `${isConstruct ? '建造' : '升级'}建筑消耗完灵资，删除`, 
                    is_recursive: false 
                });
                console.log(`✅ 消耗完灵资: ${selectedItem.name}，已删除`);
            }
        }

        // 更新建筑状态
        if (isConstruct) {
            // 建造：设置为已建成，等级设为1
            await Mvu.setMvuVariable(mvuData, `家族基建.${buildingKey}.是否建成[0]`, true, { 
                reason: '手动建造建筑', 
                is_recursive: false 
                });
            await Mvu.setMvuVariable(mvuData, `家族基建.${buildingKey}.等级[0]`, 1, { 
                reason: '建造完成，初始等级', 
                is_recursive: false 
            });
        } else {
            // 升级：等级+1
            const currentLevel = mvuData.stat_data['家族基建']?.[buildingKey]?.['等级']?.[0] || 1;
            const newLevel = currentLevel + 1;
            await Mvu.setMvuVariable(mvuData, `家族基建.${buildingKey}.等级[0]`, newLevel, { 
                reason: '手动升级建筑', 
                is_recursive: false 
            });
            console.log(`✅ 建筑升级: Lv.${currentLevel} -> Lv.${newLevel}`);
        }

        // 保存更新后的数据
        await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: targetMessageId });

        console.log(`✅ ${isConstruct ? '建造' : '升级'}成功`);

        // 显示提示
        if (isConstruct) {
            showBuildingNotification(buildingName, '建造成功！', '🔨');
        } else {
            const newLevel = mvuData.stat_data['家族基建']?.[buildingKey]?.['等级']?.[0] || 1;
            showBuildingNotification(buildingName, `升级成功！Lv.${newLevel}`, '⬆️');
        }

        // 刷新显示
        setTimeout(() => {
            loadAndDisplay();
        }, 500);

    } catch (error) {
        console.error(`❌ ${isConstruct ? '建造' : '升级'}处理失败:`, error);
        console.error('错误堆栈:', error.stack);
        const msg = `${isConstruct ? '建造' : '升级'}失败：` + error.message;
        if (typeof toastr !== 'undefined') {
            toastr.error(msg);
        } else {
            alert(msg + '\n\n详情请查看控制台');
        }
    }
}

// ========== 卸下法宝处理函数 ==========
window.handleUnequipFabao = async function(fabaoKey, fabaoName) {
    try {
        // 获取当前数据
        let targetMessageId = 'latest';
        if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
            let currentId = getLastMessageId();
            while (currentId >= 0) {
                const message = getChatMessages(currentId).at(-1);
                if (message && message.role !== 'user') {
                    targetMessageId = currentId;
                    break;
                }
                currentId--;
            }
        }

        const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

        if (!mvuData || !mvuData.stat_data) {
            toastr.error('卸下法宝失败：无法获取数据');
            return;
        }

        // 获取法宝的完整信息
        const fabaoData = mvuData.stat_data['我的信息']?.['装备法宝']?.[fabaoKey];

        if (!fabaoData) {
            toastr.error('卸下法宝失败：法宝数据不存在');
            return;
        }

        // 使用 Mvu 系统更新变量
        const currentFaqi = mvuData.stat_data['道具']?.['法器'] || {};

        // 创建新的法器对象，包含原有的和新添加的
        const newFaqi = { ...currentFaqi };
        newFaqi[fabaoKey] = fabaoData;

        // 1. 整体更新道具.法器
        await Mvu.setMvuVariable(mvuData, `道具.法器`, newFaqi, { 
            reason: '卸下法宝，添加到道具仓库', 
            is_recursive: false 
        });

        // 2. 从装备法宝中删除（设置为null）
        await Mvu.setMvuVariable(mvuData, `我的信息.装备法宝.${fabaoKey}`, null, { 
            reason: '卸下法宝', 
            is_recursive: false 
