// ========== 境界突破处理函数 ==========
window.handleBreakthrough = async function(currentRealm) {
    console.log('⚡ 开始突破境界:', currentRealm);

    try {
        // 境界顺序映射
        const realmSequence = {
            '凡人': '胎息玄景轮',
            '胎息玄景轮': '胎息周行轮',
            '胎息周行轮': '胎息眠藏轮',
            '胎息眠藏轮': '胎息呼吸轮',
            '胎息呼吸轮': '胎息灵明轮',
            '胎息灵明轮': '胎息逆返轮',
            '胎息逆返轮': '筑基前期',
            '筑基前期': '筑基中期',
            '筑基中期': '筑基后期',
            '筑基后期': '紫府境'
        };

        const nextRealm = realmSequence[currentRealm];

        if (!nextRealm) {
            console.error('❌ 无法确定下一境界');
            const msg = '突破失败：未知的境界或已达最高境界';
            if (typeof toastr !== 'undefined') {
                toastr.error(msg);
            } else {
                alert(msg);
            }
            return;
        }

        console.log(`📊 突破信息: ${currentRealm} -> ${nextRealm}`);

        // 获取当前数据
        let targetMessageId = 'latest';
        if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
            let currentId = getLastMessageId();
            while (currentId >= 0) {
                const message = getChatMessages(currentId).at(-1);
                if (message && message.role !== 'user') {
                    targetMessageId = currentId;
                    break;
                }
                currentId--;
            }
        }

        const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

        if (!mvuData || !mvuData.stat_data) {
            console.error('❌ 无法获取数据');
            const msg = '突破失败：无法获取数据';
            if (typeof toastr !== 'undefined') {
                toastr.error(msg);
            } else {
                alert(msg);
            }
            return;
        }

        // 获取突破所需灵资信息
        const myInfo = mvuData.stat_data['我的信息'] || {};
        const upgradeInfo = myInfo['升级消耗'] || {};
        const needLingziName = upgradeInfo['所需灵资名称']?.[0] || '';
        const needLingziGrade = upgradeInfo['所需灵资品级']?.[0] || 0;
        const needLingziCount = upgradeInfo['所需灵资数量']?.[0] || 0;

        console.log(`📦 所需灵资: ${needLingziName} (${needLingziGrade}品) ×${needLingziCount}`);

        if (!needLingziName) {
            console.warn('⚠️ 未配置突破所需灵资，直接突破');
            // 如果没有配置灵资需求，直接突破
            await performBreakthrough(nextRealm, null, targetMessageId);
            return;
        }

        // 从道具中查找匹配的灵资
        const itemsData = mvuData.stat_data['道具'] || {};
        const lingziData = itemsData['灵资'] || {};
        const lingziKeys = Object.keys(lingziData).filter(k => k !== '$meta');

        // 查找名称匹配的灵资
        const matchedItems = [];
        lingziKeys.forEach(key => {
            const item = lingziData[key];
            const itemName = item['名称']?.[0] || key;
            const itemGrade = item['品级']?.[0] || 0;
            const itemCount = item['数量']?.[0] || 0;
            const itemDaotong = item['道统']?.[0] || '';
            const itemEffect = item['效果']?.[0] || '';

            // 名称匹配
            if (itemName === needLingziName && itemCount > 0) {
                matchedItems.push({
                    key: key,
                    name: itemName,
                    grade: itemGrade,
                    count: itemCount,
                    daotong: itemDaotong,
                    effect: itemEffect
                });
            }
        });

        console.log(`📋 找到 ${matchedItems.length} 个匹配的灵资`);

        if (matchedItems.length === 0) {
            const msg = `突破失败：缺少所需灵资【${needLingziName}】`;
            if (typeof toastr !== 'undefined') {
                toastr.error(msg);
            } else {
                alert(msg);
            }
            return;
        }

        // 弹出选择框
        showBreakthroughItemSelector(matchedItems, needLingziName, needLingziGrade, needLingziCount, async (selectedItem) => {
            console.log('✅ 用户选择了:', selectedItem);

            // 检查数量是否足够
            if (selectedItem.count < needLingziCount) {
                const msg = `突破失败：${needLingziName}数量不足（需要${needLingziCount}个，拥有${selectedItem.count}个）`;
                if (typeof toastr !== 'undefined') {
                    toastr.error(msg);
                } else {
                    alert(msg);
                }
                return;
            }

            // 执行突破
            await performBreakthrough(nextRealm, selectedItem, targetMessageId);
        });

    } catch (error) {
        console.error('❌ 突破处理失败:', error);
        console.error('错误堆栈:', error.stack);
        const msg = '突破失败：' + error.message;
        if (typeof toastr !== 'undefined') {
            toastr.error(msg);
        } else {
            alert(msg + '\n\n详情请查看控制台');
        }
    }
};

// ========== 显示灵资选择弹窗 ==========
function showBreakthroughItemSelector(items, needName, needGrade, needCount, onConfirm) {
    console.log('📋 显示灵资选择弹窗');

    let selectedItem = null;

    // 创建弹窗HTML
    const modalHtml = `
        <div class="breakthrough-modal" id="breakthrough-modal">
            <div class="breakthrough-modal-content">
                <div class="breakthrough-modal-header">
                    <div class="breakthrough-modal-title">
                        ⚡ 选择突破灵资
                    </div>
                    <button class="breakthrough-modal-close" id="breakthrough-modal-close">×</button>
                </div>

                <div class="breakthrough-requirement">
                    <div class="breakthrough-requirement-title">突破需要</div>
                    <div class="breakthrough-requirement-content">
                        ${needName} (${needGrade}品) ×${needCount}
                    </div>
                </div>

                <div class="breakthrough-items-list" id="breakthrough-items-list">
                    ${items.map((item, index) => `
                        <div class="breakthrough-item" data-index="${index}">
                            <div class="breakthrough-item-header">
                                <div class="breakthrough-item-name">${item.name}</div>
                                <div class="breakthrough-item-count">拥有 ×${item.count}</div>
                            </div>
                            <div class="breakthrough-item-info">
                                <span>品级：${item.grade}品</span>
                                ${item.daotong ? `<span>道统：${item.daotong}</span>` : ''}
                            </div>
                            ${item.effect ? `<div style="font-size: 14px; color: #a0826d; margin-top: 4px;">${item.effect}</div>` : ''}
                        </div>
                    `).join('')}
                </div>

                <div class="breakthrough-modal-buttons">
                    <button class="breakthrough-modal-btn breakthrough-modal-btn-cancel" id="breakthrough-modal-cancel">取消</button>
                    <button class="breakthrough-modal-btn breakthrough-modal-btn-confirm" id="breakthrough-modal-confirm" disabled>确定突破</button>
                </div>
            </div>
        </div>
    `;

    // 添加到页面
    $('body').append(modalHtml);

    const $modal = $('#breakthrough-modal');
    const $itemsList = $('#breakthrough-items-list');
    const $confirmBtn = $('#breakthrough-modal-confirm');

    // 点击灵资项选择
    $itemsList.on('click', '.breakthrough-item', function() {
        const index = parseInt($(this).data('index'));
        selectedItem = items[index];

        $('.breakthrough-item').removeClass('selected');
        $(this).addClass('selected');

        $confirmBtn.prop('disabled', false);

        console.log('📦 选中灵资:', selectedItem);
    });

    // 确定按钮
    $confirmBtn.on('click', function() {
        if (selectedItem) {
            $modal.remove();
            onConfirm(selectedItem);
        }
    });

    // 取消按钮
    $('#breakthrough-modal-cancel, #breakthrough-modal-close').on('click', function() {
        $modal.remove();
    });

    // 点击背景关闭
    $modal.on('click', function(e) {
        if (e.target === this) {
            $modal.remove();
        }
    });
}

// ========== 执行突破（消耗灵资） ==========
async function performBreakthrough(nextRealm, selectedItem, targetMessageId) {
    console.log('⚡ 执行突破:', nextRealm, selectedItem);

    try {
        // 检查必要的库
        if (typeof _ === 'undefined' || typeof _.get !== 'function') {
            console.error('❌ lodash 库不可用');
            const msg = '突破失败：缺少必要的库（lodash）';
            if (typeof toastr !== 'undefined') {
                toastr.error(msg);
            } else {
                alert(msg);
            }
            return;
        }

        // 优先使用 Mvu 系统更新变量
        let updateSuccess = false;

        if (typeof Mvu !== 'undefined' && typeof Mvu.setMvuVariable === 'function') {
            console.log('✅ 使用 Mvu 系统更新变量');

            try {
                const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

                if (mvuData && mvuData.stat_data) {
                    // 获取升级消耗信息
                    const myInfo = mvuData.stat_data['我的信息'] || {};
                    const upgradeInfo = myInfo['升级消耗'] || {};
                    const needLingziCount = upgradeInfo['所需灵资数量']?.[0] || 0;
                    const currentRealm = myInfo['修炼信息']?.['境界']?.[0] || '';

                    // 更新境界
                    await Mvu.setMvuVariable(mvuData, `我的信息.修炼信息.境界[0]`, nextRealm, { 
                        reason: '手动突破境界', 
                        is_recursive: false 
                    });

                    // 重置道行为0
                    await Mvu.setMvuVariable(mvuData, `我的信息.修炼信息.道行[0]`, 0, { 
                        reason: '突破后重置道行', 
                        is_recursive: false 
                    });

                    // 清空升级消耗信息，等待AI重新填写
                    await Mvu.setMvuVariable(mvuData, `我的信息.升级消耗.所需灵资名称[0]`, '', { 
                        reason: '突破后清空升级消耗，等待AI填写', 
                        is_recursive: false 
                    });
                    await Mvu.setMvuVariable(mvuData, `我的信息.升级消耗.所需灵资品级[0]`, 1, { 
                        reason: '突破后重置品级', 
                        is_recursive: false 
                    });
                    await Mvu.setMvuVariable(mvuData, `我的信息.升级消耗.所需灵资数量[0]`, 1, { 
                        reason: '突破后重置数量', 
                        is_recursive: false 
                    });

                    // 如果有选中的灵资，消耗它
                    if (selectedItem && needLingziCount > 0) {
                        const newCount = selectedItem.count - needLingziCount;

                        if (newCount > 0) {
                            // 减少数量
                            await Mvu.setMvuVariable(mvuData, `道具.灵资.${selectedItem.key}.数量[0]`, newCount, { 
                                reason: '突破消耗灵资', 
                                is_recursive: false 
                            });
                            console.log(`✅ 消耗灵资: ${selectedItem.name} ×${needLingziCount}, 剩余 ${newCount}`);
                        } else {
                            // 数量为0，删除该灵资
                            await Mvu.setMvuVariable(mvuData, `道具.灵资.${selectedItem.key}`, null, { 
                                reason: '突破消耗完灵资，删除', 
                                is_recursive: false 
                            });
                            console.log(`✅ 消耗完灵资: ${selectedItem.name}，已删除`);
                        }
                    }

                    // 保存更新后的数据
                    await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: targetMessageId });

                    updateSuccess = true;
                    console.log('✅ Mvu 变量更新成功');
                } else {
                    console.warn('⚠️ Mvu数据为空，尝试使用 insertOrAssignVariables');
                }
            } catch (error) {
                console.error('❌ Mvu 更新失败:', error);
                console.warn('⚠️ 尝试使用 insertOrAssignVariables');
            }
        }

        // 回退到 insertOrAssignVariables
        if (!updateSuccess && typeof insertOrAssignVariables === 'function') {
            console.log('⚠️ 使用 insertOrAssignVariables 更新变量');

            const updateData = {
                '我的信息': {
                    '修炼信息': {
                        '境界': [nextRealm, '当前修炼境界'],
                        '道行': [0, '突破后重置道行']
                    },
                    '升级消耗': {
                        '所需灵资名称': ['', '突破所需灵资名称，等待AI填写'],
                        '所需灵资品级': [1, '突破所需灵资品级'],
                        '所需灵资数量': [1, '突破所需灵资数量']
                    }
                }
            };

            // 如果有选中的灵资，也更新它
            if (selectedItem) {
                // 从selectedItem获取需要消耗的数量
                const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });
                const myInfo = mvuData?.stat_data?.['我的信息'] || {};
                const upgradeInfo = myInfo['升级消耗'] || {};
                const needLingziCount = upgradeInfo['所需灵资数量']?.[0] || 1;

                if (needLingziCount > 0) {
                    const newCount = selectedItem.count - needLingziCount;

                    if (!updateData['道具']) {
                        updateData['道具'] = {};
                    }
                    if (!updateData['道具']['灵资']) {
                        updateData['道具']['灵资'] = {};
                    }

                    if (newCount > 0) {
                        updateData['道具']['灵资'][selectedItem.key] = {
                            '数量': [newCount, '拥有数量']
                        };
                        console.log(`✅ 消耗灵资: ${selectedItem.name} ×${needLingziCount}, 剩余 ${newCount}`);
                    } else {
                        // 数量为0时，设置为null会删除该key
                        updateData['道具']['灵资'][selectedItem.key] = null;
                        console.log(`✅ 消耗完灵资: ${selectedItem.name}，已删除`);
                    }
                }
            }

            await insertOrAssignVariables(updateData, { type: 'chat' });

            updateSuccess = true;
            console.log('✅ 变量更新成功');
        }

        if (!updateSuccess) {
            console.error('❌ 所有变量更新方法都失败了');
            const msg = '突破失败：无法更新变量';
            if (typeof toastr !== 'undefined') {
                toastr.error(msg);
            } else {
                alert(msg);
            }
            return;
        }

        console.log('✅ 境界突破成功');

        // 显示突破动画
        const currentRealm = ''; // 这里可以从之前的数据获取，但不影响显示
        showBreakthroughNotification(currentRealm || '当前境界', nextRealm);

        // 刷新显示
        setTimeout(() => {
            loadAndDisplay();
        }, 1000);

    } catch (error) {
        console.error('❌ 突破处理失败:', error);
        console.error('错误堆栈:', error.stack);
        const msg = '突破失败：' + error.message;
        if (typeof toastr !== 'undefined') {
            toastr.error(msg);
        } else {
            alert(msg + '\n\n详情请查看控制台');
        }
    }
};

