// 赠予功能
window.handleMemberGift = async function(characterKey, characterName) {
    console.log(`🎁 开始赠予流程给${characterName}...`);

    try {
        // 获取当前数据
        let targetMessageId = 'latest';
        if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
            let currentId = getLastMessageId();
            while (currentId >= 0) {
                const message = getChatMessages(currentId).at(-1);
                if (message && message.role !== 'user') {
                    targetMessageId = currentId;
                    break;
                }
                currentId--;
            }
        }

        const data = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });
        if (!data || !data.stat_data) {
            console.error('[Member Gift] 无法获取数据');
            if (typeof toastr !== 'undefined') {
                toastr.error('无法获取道具数据');
            }
            return;
        }

        const itemsData = data.stat_data['道具'];
        if (!itemsData) {
            if (typeof toastr !== 'undefined') {
                toastr.warning('暂无可赠予的道具');
            }
            return;
        }

        // 收集所有道具
        const allItems = [];
        const categories = ['灵资', '法器', '丹药', '其他'];

        categories.forEach(category => {
            const categoryData = itemsData[category];
            if (categoryData) {
                const itemKeys = Object.keys(categoryData).filter(k => k !== '$meta' && categoryData[k] !== null);
                itemKeys.forEach(key => {
                    const item = categoryData[key];
                    const name = item.名称?.[0] || key;
                    const count = item.数量?.[0] || 0;
                    if (count > 0) {
                        allItems.push({
                            key,
                            name,
                            count,
                            category
                        });
                    }
                });
            }
        });

        if (allItems.length === 0) {
            if (typeof toastr !== 'undefined') {
                toastr.warning('暂无可赠予的道具');
            }
            return;
        }

        // 创建弹窗选择道具
        const modal = $(`
            <div style="
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(0, 0, 0, 0.7);
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 9999;
            ">
                <div style="
                    background: linear-gradient(135deg, #1e2430 0%, #2a2f3f 100%);
                    border: 1px solid rgba(255, 255, 255, 0.1);
                    border-radius: 20px;
                    padding: 30px;
                    max-width: 500px;
                    width: 90%;
                    max-height: 70vh;
                    overflow: hidden;
                    display: flex;
                    flex-direction: column;
                ">
                    <div style="
                        font-size: 24px;
                        font-weight: 600;
                        color: #fbbf24;
                        margin-bottom: 20px;
                        text-align: center;
                    ">
                        🎁 选择赠予给 ${characterName} 的道具
                    </div>

                    <div style="
                        flex: 1;
                        overflow-y: auto;
                        margin-bottom: 20px;
                    " class="gift-items-list">
                        ${allItems.map(item => `
                            <label style="
                                display: flex;
                                align-items: center;
                                padding: 12px;
                                background: rgba(255, 255, 255, 0.05);
                                border-radius: 8px;
                                margin-bottom: 8px;
                                cursor: pointer;
                                transition: all 0.3s;
                            " onmouseover="this.style.background='rgba(255, 255, 255, 0.1)'" onmouseout="this.style.background='rgba(255, 255, 255, 0.05)'">
                                <input type="checkbox" value="${item.key}" data-category="${item.category}" data-name="${item.name}" style="
                                    width: 18px;
                                    height: 18px;
                                    margin-right: 12px;
                                    cursor: pointer;
                                ">
                                <div style="flex: 1;">
                                    <div style="color: #4a9eff; font-weight: 600; font-size: 14px;">${item.name}</div>
                                    <div style="color: #9ca3af; font-size: 14px; margin-top: 2px;">${item.category} · 数量: ${item.count}</div>
                                </div>
                            </label>
                        `).join('')}
                    </div>

                    <div style="display: flex; gap: 12px;">
                        <button class="gift-cancel-btn" style="
                            flex: 1;
                            padding: 12px;
                            background: rgba(239, 68, 68, 0.2);
                            border: 1px solid rgba(239, 68, 68, 0.5);
                            border-radius: 8px;
                            color: #ef4444;
                            font-size: 16px;
                            font-weight: 600;
                            cursor: pointer;
                            transition: all 0.3s;
                        ">
                            取消
                        </button>
                        <button class="gift-confirm-btn" style="
                            flex: 1;
                            padding: 12px;
                            background: linear-gradient(135deg, rgba(251, 191, 36, 0.3), rgba(245, 158, 11, 0.3));
                            border: 1px solid rgba(251, 191, 36, 0.5);
                            border-radius: 8px;
                            color: #fbbf24;
                            font-size: 16px;
                            font-weight: 600;
                            cursor: pointer;
                            transition: all 0.3s;
                        ">
                            确定赠予
                        </button>
                    </div>
                </div>
            </div>
        `);

        $('body').append(modal);

        // 取消按钮
        modal.find('.gift-cancel-btn').on('click', function() {
            modal.remove();
        });

        // 确定按钮
        modal.find('.gift-confirm-btn').on('click', async function() {
            const selectedItems = [];
            modal.find('input[type="checkbox"]:checked').each(function() {
                selectedItems.push($(this).data('name'));
            });

            if (selectedItems.length === 0) {
                if (typeof toastr !== 'undefined') {
                    toastr.warning('请至少选择一个道具');
                }
                return;
            }

            modal.remove();

            // 检查 triggerSlash 函数是否存在
            if (typeof triggerSlash !== 'function') {
                console.error('[Member Gift] triggerSlash 函数不可用');
                if (typeof toastr !== 'undefined') {
                    toastr.error('操作失败：系统函数不可用');
                }
                return;
            }

            // 构建赠予消息
            const itemsText = selectedItems.join('、');
            const message = `<Request:Meta-instructions：接下来你要，按照当前剧情，设计一段赠予的剧情，我想把${itemsText}送给${characterName}，注意更新道具信息变量> 我将${itemsText}送给了${characterName}`;

            // 发送消息
            await triggerSlash(`/send ${message}`);
            await triggerSlash('/trigger');

            console.log('[Member Gift] 赠予请求已发送');

            if (typeof toastr !== 'undefined') {
                toastr.success(`正在将${itemsText}赠予${characterName}...`, '赠予', {
                    timeOut: 2000
                });
            }
        });

    } catch (error) {
        console.error('[Member Gift] 赠予失败:', error);
        throw error;
    }
};

