                toastr.error('操作失败：系统函数不可用');
            }
            return;
        }

        // 计算战力比
        const ratio = targetPower > 0 ? myPower / targetPower : 99;

        // 根据战力比判断战斗结果描述
        let battleOutcome = '';
        let resultDescription = '';
        let notificationType = 'info';

        if (ratio > 2.0) {
            // 完全碾压
            battleOutcome = '完全碾压';
            resultDescription = '我的实力远超对方，战斗轻松取胜';
            notificationType = 'success';
        } else if (ratio >= 1.5) {
            // 优势明显
            battleOutcome = '优势明显';
            resultDescription = '我实力明显占优，战斗取得胜利';
            notificationType = 'success';
        } else if (ratio >= 1.2) {
            // 略占上风
            battleOutcome = '略占上风';
            resultDescription = '我略微占优，经过一番激战获胜';
            notificationType = 'success';
        } else if (ratio >= 0.9) {
            // 势均力敌
            battleOutcome = '势均力敌';
            resultDescription = '双方实力相当，战斗结果难以预料';
            notificationType = 'warning';
        } else if (ratio >= 0.67) {
            // 略处下风
            battleOutcome = '略处下风';
            resultDescription = '对方实力稍强，战斗陷入苦战';
            notificationType = 'warning';
        } else if (ratio >= 0.5) {
            // 劣势明显
            battleOutcome = '劣势明显';
            resultDescription = '对方实力明显更强，战斗极其艰难';
            notificationType = 'error';
        } else {
            // 难以匹敌
            battleOutcome = '难以匹敌';
            resultDescription = '对方实力远超于我，战斗几乎没有胜算';
            notificationType = 'error';
        }

        // 构建攻击消息
        const message = `<Request:Meta-instructions：接下来你要，按照当前剧情，设计一段与${characterName}战斗的故事，我的战斗力为${myPower}，对方战斗力为${targetPower}，战力对比为【${battleOutcome}】，${resultDescription}，注意更新变量> 对${characterName}发起攻击`;

        // 发送消息
        await triggerSlash(`/send ${message}`);
        await triggerSlash('/trigger');

        console.log('[Target Attack] 攻击请求已发送');

        // 显示不同类型的提示
        if (typeof toastr !== 'undefined') {
            const toastMessage = `正在对${characterName}发起攻击...\n战力比: ${ratio.toFixed(2)} (${battleOutcome})`;

            if (notificationType === 'success') {
                toastr.success(toastMessage, '攻击', { timeOut: 3000 });
            } else if (notificationType === 'warning') {
                toastr.warning(toastMessage, '攻击', { timeOut: 3000 });
            } else {
                toastr.error(toastMessage, '攻击', { timeOut: 3000 });
            }
        }
    } catch (error) {
        console.error('[Target Attack] 攻击失败:', error);
        throw error;
    }
};

