        // 获取拍卖行物品的完整信息
        const auctionItemData = mvuData.stat_data['拍卖行']?.[itemCategory]?.[itemKey];

        if (!auctionItemData) {
            toastr.error('购买失败：物品数据不存在');
            return;
        }

        // 创建物品副本，去掉价格字段
        const itemDataForInventory = { ...auctionItemData };
        delete itemDataForInventory['价格'];

        // 1. 添加到道具仓库
        const currentItems = mvuData.stat_data['道具']?.[itemCategory] || {};
        const newItems = { ...currentItems };
        newItems[itemKey] = itemDataForInventory;

        await Mvu.setMvuVariable(mvuData, `道具.${itemCategory}`, newItems, { 
            reason: '从拍卖行购买物品', 
            is_recursive: false 
        });

        // 2. 从拍卖行删除
        await Mvu.setMvuVariable(mvuData, `拍卖行.${itemCategory}.${itemKey}`, null, { 
            reason: '物品已被购买', 
            is_recursive: false 
        });

        // 3. 扣除灵石
        const newLingshi = lingshi - itemPrice;
        await Mvu.setMvuVariable(mvuData, `家族信息.灵石[0]`, newLingshi, { 
            reason: '购买物品花费灵石', 
            is_recursive: false 
        });

        // 保存更新
        await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: targetMessageId });

        console.log('✅ 购买成功');

        if (typeof toastr !== 'undefined') {
            toastr.success(`成功购买【${itemName}】，花费${itemPrice}灵石`, '购买成功', {
                timeOut: 2000
            });
        }

        // 刷新显示
        setTimeout(() => {
            loadAndDisplay();
        }, 500);

    } catch (error) {
        console.error('[Buy Item] 购买失败:', error);
        throw error;
    }
};

