              console.log('找到的targetBtn:', targetBtn);

              if (targetBtn && targetBtn.classList.contains('option-btn')) {
                const wasSelected = targetBtn.classList.contains('selected');
                const itemCost = parseInt(targetBtn.dataset.cost) || 0;

                // 如果是要选中（而不是取消选中），检查属性点是否足够
                if (!wasSelected && itemCost > 0) {
                  const currentUsed = calculateUsedPoints();
                  const currentRemaining = totalPoints - currentUsed;

                  // 对于单选模式，计算替换后的消耗
                  if (grid.classList.contains('single-select')) {
                    const currentSelected = grid.querySelector('.option-btn.selected');
                    const currentCost = currentSelected ? (parseInt(currentSelected.dataset.cost) || 0) : 0;
                    const netCost = itemCost - currentCost; // 新增消耗 = 新选项成本 - 旧选项成本

                    if (currentRemaining - netCost < 0) {
                      showNotification(`该选项需要 ${itemCost} 点，当前剩余 ${currentRemaining} 点`, '属性点不足！', 'error');
                      return;
                    }
                  } else {
                    // 多选模式，直接检查是否足够
                    if (currentRemaining - itemCost < 0) {
                      showNotification(`该选项需要 ${itemCost} 点，当前剩余 ${currentRemaining} 点`, '属性点不足！', 'error');
                      return;
                    }
                  }
                }

                // 检查是否为单选模式
                if (grid.classList.contains('single-select')) {
            // 单选模式特殊处理：如果点击已选中的按钮，则取消选择
                  if (wasSelected) {
                    targetBtn.classList.remove('selected');
                    targetBtn.removeAttribute('data-user-selected');
            } else {
              // 清除其他选择，只选中当前项
                    grid.querySelectorAll('.option-btn').forEach(btn => {
                      btn.classList.remove('selected');
                      btn.removeAttribute('data-user-selected');
              });
                    targetBtn.classList.add('selected');
                    targetBtn.setAttribute('data-user-selected', 'true');
            }
          } else {
            // 多选模式：切换选中状态
                  if (wasSelected) {
                    targetBtn.classList.remove('selected');
                    targetBtn.removeAttribute('data-user-selected');
            } else {
                    targetBtn.classList.add('selected');
                    targetBtn.setAttribute('data-user-selected', 'true');
            }
                }

                updateSelectedItems(grid.id.replace('Grid', ''));
                updateRemainingPoints(); // 更新剩余属性点
        }
      } catch (error) {
              console.error('点击事件处理错误:', error);
      }
    });
  });

        // 设置自定义输入框的事件监听器
