                <div style="display: flex; flex-direction: column; gap: 8px;">
                    ${forceKeys.map(forceName => {
                        const force = contactedForces[forceName];
                        const relation = force.关系?.[0] || '未知';
                        const desc = force.描述?.[0] || '';

                        // 根据关系类型显示不同颜色
                        let relationColor = '#9ca3af';
                        if (relation.includes('归附') || relation.includes('友好') || relation.includes('盟友')) {
                            relationColor = '#22c55e';
                        } else if (relation.includes('敌对') || relation.includes('仇视') || relation.includes('战争')) {
                            relationColor = '#ef4444';
                        } else if (relation.includes('中立') || relation.includes('平和')) {
                            relationColor = '#fbbf24';
                        }

                        return `
                        <div style="padding: 8px 12px; background: rgba(245, 235, 215, 0.3); border-radius: 8px; border-left: 3px solid ${relationColor};">
                            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
                                <span style="color: #8b4513; font-weight: 600; font-size: 14px;">${forceName}</span>
                                <span style="color: ${relationColor}; font-size: 14px;">${relation}</span>
                            </div>
                            ${desc ? `<div style="color: #a0826d; font-size: 14px;">${desc}</div>` : ''}
                        </div>
                        `;
                    }).join('')}
                </div>
                ` : `
                <div style="padding: 20px; text-align: center; color: #a0826d; font-size: 14px; background: rgba(245, 235, 215, 0.3); border-radius: 6px;">
                    暂无接触势力
                </div>
                `}
            </div>
        </div>
    </div>
    `;
}

// ========== 生成道具 ==========
function generateItems(itemsData) {
    if (!itemsData) {
        return `
        <div class="section">
            <div class="section-title">🎁 道具</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">暂无道具数据</div>
            </div>
        </div>
        `;
    }

    // 辅助函数：获取品级颜色class
    function getGradeClass(grade, isWeapon = false) {
        if (isWeapon) {
            // 法器品级
            if (grade === '法器') return 'grade-faqi';
            if (grade === '灵器') return 'grade-lingqi';
            if (grade === '灵宝') return 'grade-lingbao';
            if (grade === '法宝') return 'grade-fabao';
            if (grade === '仙器') return 'grade-xianqi';
            return 'grade-lingqi';
        } else {
            // 1-9品
            if (grade >= 1 && grade <= 3) return 'grade-1';
            if (grade >= 4 && grade <= 6) return 'grade-4';
            if (grade >= 7 && grade <= 9) return 'grade-7';
            return 'grade-1';
        }
    }

    // 辅助函数：品级显示文本
    function getGradeText(grade, isWeapon = false) {
        if (isWeapon) {
            return grade;
        } else {
            const gradeNames = ['', '一品', '二品', '三品', '四品', '五品', '六品', '七品', '八品', '九品'];
            return gradeNames[grade] || `${grade}品`;
        }
    }

    // 生成各类道具的HTML
    const categories = [
        { key: '灵资', name: '灵资', icon: '💊', color: '#22c55e' },
        { key: '法器', name: '法器', icon: '⚔️', color: '#8b5cf6' },
        { key: '杂物', name: '杂物', icon: '📦', color: '#9ca3af' },
        { key: '功法', name: '功法', icon: '📜', color: '#f59e0b' },
        { key: '法术', name: '法术', icon: '✨', color: '#ec4899' }
    ];

    let totalCount = 0;
    let tabsHtml = '';
    let panelsHtml = '';
    let firstTab = true;

    categories.forEach(category => {
        const categoryData = itemsData[category.key] || {};
        const itemKeys = Object.keys(categoryData).filter(k => k !== '$meta' && categoryData[k] !== null);
        const itemCount = itemKeys.length;
        totalCount += itemCount;

        // 生成Tab
        tabsHtml += `
            <div class="item-tab ${firstTab ? 'active' : ''}" data-item-tab="${category.key}">
                ${category.icon} ${category.name} (${itemCount})
    </div>
    `;

        // 生成面板内容
        let itemsHtml = '';

        if (itemCount === 0) {
            itemsHtml = `
                <div style="padding: 40px 20px; text-align: center; color: #9ca3af;">
                    <div style="font-size: 48px; margin-bottom: 12px; opacity: 0.3;">${category.icon}</div>
                    <div style="font-size: 14px;">暂无${category.name}</div>
        </div>
        `;
        } else {
            const isWeaponCategory = category.key === '法器';

            itemsHtml = '<div class="item-grid">' + itemKeys.map(key => {
                const item = categoryData[key];
                const name = item.名称?.[0] || key;
                const daotong = item.道统?.[0] || '';
                const grade = item.品级?.[0] || (isWeaponCategory ? '法器' : 1);
                const count = item.数量?.[0] || 1;

                const gradeClass = getGradeClass(grade, isWeaponCategory);
                const gradeText = getGradeText(grade, isWeaponCategory);

                let contentHtml = '';

                if (category.key === '灵资') {
                    const effect = item.效果?.[0] || '';
                    contentHtml = `
                        ${effect ? `<div class="item-description">${effect}</div>` : ''}
                    `;
                } else if (category.key === '法器') {
                    const isBenming = item.是否本命?.[0] || false;
                    const action = item.作用?.[0] || '';
                    const powerBoost = item.战力提升?.[0] || 0;
                    contentHtml = `
                        ${isBenming ? `<div class="item-benming">本命</div>` : ''}
                        ${action ? `<div class="item-description">${action}</div>` : ''}
                        ${powerBoost > 0 ? `<div class="item-power">⚡ 战力+${powerBoost}%</div>` : ''}
                        <button class="equip-fabao-btn" data-fabao-key="${key}" data-fabao-name="${name}">
                            <span class="btn-icon">⚔️</span>
                            <span>装备</span>
                        </button>
                    `;
                } else if (category.key === '杂物') {
                    const desc = item.说明?.[0] || '';
                    contentHtml = `
                        ${desc ? `<div class="item-description">${desc}</div>` : ''}
                    `;
                } else if (category.key === '功法') {
                    const effect = item.效果?.[0] || '';
                    contentHtml = `
                        ${effect ? `<div class="item-description">${effect}</div>` : ''}
                    `;
                } else if (category.key === '法术') {
                    const power = item.威力?.[0] || 0;
                    const consume = item.法力消耗?.[0] || 0;
                    const desc = item.描述?.[0] || '';
                    contentHtml = `
                        <div class="item-power">⚡ 威力${power} | 💧耗${consume}</div>
                        ${desc ? `<div class="item-description">${desc}</div>` : ''}
