// ========== 生成家族成员 ==========
function generateCharacterBonds(bonds, myPower) {
    const characters = Object.keys(bonds).filter(k => k !== '$meta' && bonds[k] !== null);

    if (characters.length === 0) {
        return `
        <div class="section">
            <div class="section-title">💖 家族成员</div>
