// ========== 生成地图系统 ==========
function generateMap(map) {
    let envHtml = '';
    if (map.周边环境) {
        const places = Object.keys(map.周边环境).filter(k => k !== '$meta');
        if (places.length > 0) {
            envHtml = places.map(placeName => {
                const place = map.周边环境[placeName];
                const distance = place.距离?.[0] || 0;
                const desc = place.描述?.[0] || '';

                return `
                <div class="map-location">
                    <div class="location-name">${placeName}</div>
                    <div style="font-size: 14px;">${distance}米</div>
                    ${desc ? `<div style="font-size: 14px; color: #9ca3af; margin-top: 2px;">${desc}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    let locationsHtml = '';
    if (map.可探索地点) {
        const locations = Object.keys(map.可探索地点).filter(k => k !== '$meta');
        if (locations.length > 0) {
            locationsHtml = locations.map(locName => {
                const loc = map.可探索地点[locName];
                const locDesc = loc.描述?.[0] || '';
                const locStatus = loc.状态?.[0] || '';
                const locType = loc.类型?.[0] || '';

                return `
                <div class="map-location ${locStatus === '当前位置' ? 'active' : ''}">
                    <div class="location-name">${locName}</div>
                    ${locType ? `<div style="font-size: 14px; color: #9ca3af;">${locType}</div>` : ''}
                    ${locStatus ? `<div style="color: #4ade80; font-size: 14px;">(${locStatus})</div>` : ''}
                    ${locDesc ? `<div style="font-size: 14px; color: #9ca3af; margin-top: 2px;">${locDesc}</div>` : ''}
                </div>
                `;
            }).join('');
        }
    }

    return `
    <div class="section">
        <div class="section-title">🗺️ 地图系统</div>
        <div class="section-content">
            ${envHtml ? `
            <div style="margin-bottom: ${locationsHtml ? '15px' : '0'};">
                <div class="status-label" style="margin-bottom: 5px;">周边环境</div>
                <div class="map-grid">
                    ${envHtml}
                </div>
            </div>
            ` : ''}

            ${locationsHtml ? `
            <div>
                <div class="status-label" style="margin-bottom: 5px;">可探索地点</div>
                <div class="map-grid">
                    ${locationsHtml}
                </div>
            </div>
            ` : ''}

            ${!envHtml && !locationsHtml ? `
            <div style="padding: 20px; text-align: center; color: #9ca3af;">
                暂无地图数据
            </div>
            ` : ''}
        </div>
    </div>
    `;
}

