// ========== 生成家族基建 ==========
function generateFamilyBuildings(buildingsData) {
    if (!buildingsData) {
        return `
        <div class="section">
            <div class="section-title">🏛️ 家族基建</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">暂无家族基建数据</div>
            </div>
        </div>
        `;
    }

    // 建筑图标映射
    const buildingIcons = {
        '祠堂': '🏮',
        '大阵': '⚡',
        '山门': '🚪',
        '坊市': '🏪',
        '修炼室': '🧘',
        '灵植': '🌱',
        '灵脉': '💎',
        '洞华天': '🌌'
    };

    // 获取所有建筑
    const buildingKeys = Object.keys(buildingsData).filter(k => k !== '$meta');

    if (buildingKeys.length === 0) {
        return `
        <div class="section">
            <div class="section-title">🏛️ 家族基建</div>
            <div class="section-content">
                <div style="padding: 20px; text-align: center; color: #9ca3af;">
                    <div style="font-size: 48px; margin-bottom: 12px; opacity: 0.3;">🏛️</div>
                    <div style="font-size: 14px;">暂无建筑</div>
                </div>
            </div>
        </div>
        `;
    }

    // 统计已建成和未建成的数量
    let builtCount = 0;
    let unbuiltCount = 0;
    buildingKeys.forEach(key => {
        const isBuilt = buildingsData[key].是否建成?.[0] || false;
        if (isBuilt) {
            builtCount++;
        } else {
            unbuiltCount++;
        }
    });

    const buildingsHtml = buildingKeys.map(buildingKey => {
        const building = buildingsData[buildingKey];
        const name = building.名称?.[0] || buildingKey;
        const intro = building.介绍?.[0] || '';
        const effect = building.效果?.[0] || '';
        const level = building.等级?.[0] || 0;
        const isBuilt = building.是否建成?.[0] || false;

        const icon = buildingIcons[buildingKey] || '🏛️';

        // 根据是否建成选择消耗数据
        let costData, costTitle, btnText, btnIcon;
        if (isBuilt) {
            costData = building.升级消耗 || {};
            costTitle = '📦 升级消耗';
            btnText = '升级建筑';
            btnIcon = '⬆️';
        } else {
            costData = building.建造消耗 || {};
            costTitle = '🔨 建造消耗';
            btnText = '建造建筑';
            btnIcon = '🔨';
        }

        const lingshi = costData.灵石?.[0] || 0;
        const lingziGrade = costData.灵资品级?.[0] || 0;
        const lingziCount = costData.灵资数量?.[0] || 0;

        // 等级显示
        const levelDisplay = isBuilt ? `Lv.${level}` : '<span style="color: #9ca3af;">未建成</span>';

        // 未建成的建筑添加 unbuilt class
        const cardClass = isBuilt ? 'building-card' : 'building-card unbuilt';

        return `
        <div class="${cardClass}">
            <div class="building-header">
                <div class="building-name">
                    <span>${icon}</span>
                    <span>${name}</span>
                </div>
                <div class="building-level">${levelDisplay}</div>
            </div>

            <div class="building-intro">${intro}</div>

            <div class="building-effect">
                <div class="building-effect-label">✨ 建筑效果</div>
                <div class="building-effect-value">${effect}</div>
            </div>

            <div class="building-cost">
                <div class="building-cost-title">${costTitle}</div>
                <div class="building-cost-items">
                    <div class="building-cost-item">💎 ${lingshi}灵石</div>
                    <div class="building-cost-item">💊 ${lingziGrade}品灵资 ×${lingziCount}</div>
                </div>
            </div>

            <button class="building-upgrade-btn" 
                data-building="${buildingKey}" 
                data-building-name="${name}"
                data-is-built="${isBuilt}"
                data-lingshi-cost="${lingshi}"
                data-lingzi-grade="${lingziGrade}"
                data-lingzi-count="${lingziCount}">
                ${btnIcon} ${btnText}
            </button>
        </div>
        `;
    }).join('');

    return `
    <div class="section">
        <div class="section-title">🏛️ 家族基建 (共${buildingKeys.length}座：<span style="color: #22c55e;">${builtCount}已建成</span> / <span style="color: #9ca3af;">${unbuiltCount}未建成</span>)</div>
        <div class="section-content">
            <div class="building-grid">
                ${buildingsHtml}
            </div>
        </div>
    </div>
    `;
}

// ========== 样式切换功能 ==========
let currentCardStyle = 1;
function toggleCardStyle() {
    currentCardStyle = currentCardStyle === 1 ? 2 : 1;
    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
    $container.attr('data-style', `style${currentCardStyle}`);
    console.log(`✨ 切换到样式${currentCardStyle}`);
}

// ========== 初始化卡片样式 ==========
function initializeCardStyles() {
    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');
    $container.attr('data-style', 'style1');
    console.log('✅ 卡片样式初始化为 style1');
}

// ========== 设置事件委托 ==========
function setupEventDelegation() {
    const $container = window.top ? $(window.top.document).find('#village-card-status') : $('#village-card-status');

    // 移除旧的事件绑定
    $container.off('click');

    // 使用事件委托绑定所有按钮点击事件
    $container.on('click', '[data-action]', async function(e) {
        e.preventDefault();
        e.stopPropagation();

        const $btn = $(this);
        const action = $btn.data('action');

        console.log('🔔 按钮被点击:', action);

        if ($btn.prop('disabled')) {
            console.warn('⚠️ 按钮已禁用，忽略点击');
            return;
        }

        try {
            switch(action) {
                case 'toggle-style':
                    console.log('🎨 切换样式...');
                    toggleCardStyle();
                    break;

                case 'refresh':
                    console.log('🔄 开始刷新数据...');
                    $btn.addClass('refreshing').prop('disabled', true);

                    try {
                        console.log('🔧 触发重新处理变量...');
                        await reprocessCurrentMessageVariables();

                        console.log('⏳ 等待变量处理完成...');
                        await new Promise(resolve => setTimeout(resolve, 500));

                        console.log('🔄 刷新显示数据...');
                        // 不要先清除，让loadAndDisplay内部处理替换
                        loadAndDisplay();

                        console.log('✅ 刷新完成');
                    } finally {
                        setTimeout(() => {
                            $btn.removeClass('refreshing').prop('disabled', false);
                        }, 500);
                    }
                    break;

                case 'toggle-collapse':
                    console.log('📌 切换收起状态');
                    // 确保在正确的DOM上下文中查找元素
                    const $container = window.top ? $(window.top.document) : $(document);
                    const $cardWrapper = $container.find('.village-card-wrapper');
                    console.log('找到卡片容器:', $cardWrapper.length);

                    $cardWrapper.toggleClass('collapsed');

                    const isCollapsed = $cardWrapper.hasClass('collapsed');
                    console.log('当前状态:', isCollapsed ? '已收起' : '已展开');
                    $btn.find('span').text(isCollapsed ? '📍' : '📌');
                    $btn.attr('title', isCollapsed ? '展开' : '收起');
                    break;

                default:
                    console.warn('⚠️ 未知的操作:', action);
            }
        } catch (error) {
            console.error('❌ 操作失败:', error);
            if (typeof toastr !== 'undefined') {
                toastr.error('操作失败：' + error.message);
            }
        }
    });

    // Tab切换事件
    $container.on('click', '.village-tab', function(e) {
        e.preventDefault();
        e.stopPropagation();

        const $tab = $(this);
        const tabKey = $tab.data('tab');

        console.log('📑 切换到Tab:', tabKey);

        // 切换Tab激活状态
        $('.village-tab').removeClass('active');
        $tab.addClass('active');

