// ========== 建筑建造处理函数 ==========
window.handleBuildingConstruct = async function(buildingKey, buildingName, lingshiCost, lingziGrade, lingziCount) {
    console.log('🔨 开始建造建筑:', buildingKey, '消耗:', {lingshiCost, lingziGrade, lingziCount});

    try {
        // 获取当前数据
        let targetMessageId = 'latest';
        if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
            let currentId = getLastMessageId();
            while (currentId >= 0) {
                const message = getChatMessages(currentId).at(-1);
                if (message && message.role !== 'user') {
                    targetMessageId = currentId;
                    break;
                }
                currentId--;
            }
        }

        const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

        if (!mvuData || !mvuData.stat_data) {
            toastr.error('建造失败：无法获取数据');
            return;
        }

        // 检查灵石是否足够
        const currentLingshi = mvuData.stat_data['家族信息']?.['灵石']?.[0] || 0;
        if (currentLingshi < lingshiCost) {
            toastr.error(`灵石不足！需要 ${lingshiCost} 块，当前 ${currentLingshi} 块`);
            return;
        }

        // 如果不需要灵资，直接建造
        if (lingziCount === 0 || lingziGrade === 0) {
            await performBuildingOperation(buildingKey, buildingName, true, null, targetMessageId, lingshiCost);
            return;
        }

        // 从道具中查找符合品级的灵资
        const itemsData = mvuData.stat_data['道具'] || {};
        const lingziData = itemsData['灵资'] || {};
        const lingziKeys = Object.keys(lingziData).filter(k => k !== '$meta' && lingziData[k] !== null);

        // 查找品级匹配的灵资
        const matchedItems = [];
        lingziKeys.forEach(key => {
            const item = lingziData[key];
            const itemName = item['名称']?.[0] || key;
            const itemGrade = item['品级']?.[0] || 0;
            const itemCount = item['数量']?.[0] || 0;
            const itemDaotong = item['道统']?.[0] || '';
            const itemEffect = item['效果']?.[0] || '';

            // 品级匹配（需要品级或更高）
            if (itemGrade >= lingziGrade && itemCount > 0) {
                matchedItems.push({
                    key: key,
                    name: itemName,
                    grade: itemGrade,
                    count: itemCount,
                    daotong: itemDaotong,
                    effect: itemEffect
                });
            }
        });

        console.log(`📋 找到 ${matchedItems.length} 个符合条件的灵资（需要${lingziGrade}品及以上）`);

        if (matchedItems.length === 0) {
            toastr.error(`建造失败：缺少 ${lingziGrade}品 及以上灵资`);
            return;
        }

        // 弹出选择框
        showBuildingResourceSelector(
            matchedItems, 
            buildingName, 
            lingziGrade, 
            lingziCount, 
            lingshiCost,
            true,
            async (selectedItem) => {
                console.log('✅ 用户选择了:', selectedItem);

                // 检查数量是否足够
                if (selectedItem.count < lingziCount) {
                    toastr.error(`建造失败：灵资数量不足（需要${lingziCount}个，拥有${selectedItem.count}个）`);
                    return;
                }

                // 执行建造
                await performBuildingOperation(buildingKey, buildingName, true, selectedItem, targetMessageId, lingshiCost, lingziCount);
            }
        );

    } catch (error) {
        console.error('❌ 建造处理失败:', error);
        console.error('错误堆栈:', error.stack);
        const msg = '建造失败：' + error.message;
        if (typeof toastr !== 'undefined') {
            toastr.error(msg);
        } else {
            alert(msg + '\n\n详情请查看控制台');
        }
    }
};

