// 双修功能
window.handleMemberCultivate = async function(characterKey, characterName, favorability) {
    console.log(`☯️ 开始双修请求给${characterName}，好感度: ${favorability}...`);

    try {
        // 检查 triggerSlash 函数是否存在
        if (typeof triggerSlash !== 'function') {
            console.error('[Member Cultivate] triggerSlash 函数不可用');
            if (typeof toastr !== 'undefined') {
                toastr.error('操作失败：系统函数不可用');
            }
            return;
        }

        // 根据好感度分8个档次
        let difficultyText = '';
        let successRate = '';

        if (favorability >= 80) {
            // 80-100: 深厚情感
            difficultyText = '我与她情深意重，双修水到渠成';
            successRate = '极易成功';
        } else if (favorability >= 60) {
            // 60-79: 好感/友好
            difficultyText = '我与她关系友好，双修有较大可能成功';
            successRate = '较易成功';
        } else if (favorability >= 40) {
            // 40-59: 略有好感
            difficultyText = '我与她略有好感，双修有一定可能成功';
            successRate = '可能成功';
        } else if (favorability >= 20) {
            // 20-39: 初识/中立
            difficultyText = '我与她关系平平，双修需要一些说服';
            successRate = '需要说服';
        } else if (favorability >= 0) {
            // 0-19: 陌生/中立
            difficultyText = '我与她关系普通，双修很难说服她';
            successRate = '较难成功';
        } else if (favorability >= -30) {
            // -29 to -1: 不喜欢/反感
            difficultyText = '我与她关系不佳，双修极难成功';
            successRate = '很难成功';
        } else if (favorability >= -60) {
            // -59 to -30: 敌对
            difficultyText = '我与她关系敌对，双修几乎不可能成功';
            successRate = '几乎不可能';
        } else {
            // -100 to -60: 仇恨
            difficultyText = '我与她势同水火，双修完全不可能成功';
            successRate = '绝无可能';
        }

        // 构建双修消息
        const message = `<Request:Meta-instructions：接下来你要，按照当前剧情，设计一段请求与${characterName}双修的故事，我与她的好感度为${favorability}，${difficultyText}，${successRate}> 与${characterName}提出双修邀请`;

        // 发送消息
        await triggerSlash(`/send ${message}`);
        await triggerSlash('/trigger');

        console.log('[Member Cultivate] 双修请求已发送');

        if (typeof toastr !== 'undefined') {
            toastr.info(`正在向${characterName}提出双修邀请...\n好感度: ${favorability} (${successRate})`, '双修', {
                timeOut: 3000
            });
        }
    } catch (error) {
        console.error('[Member Cultivate] 双修请求失败:', error);
        throw error;
    }
};

// 攻击功能
window.handleTargetAttack = async function(characterKey, characterName, myPower, targetPower) {
    console.log(`⚔️ 开始攻击${characterName}，我的战力: ${myPower}, 对方战力: ${targetPower}...`);

    try {
        // 检查 triggerSlash 函数是否存在
        if (typeof triggerSlash !== 'function') {
            console.error('[Target Attack] triggerSlash 函数不可用');
            if (typeof toastr !== 'undefined') {
                toastr.error('操作失败：系统函数不可用');
            }
            return;
        }

        // 计算战力比
        const ratio = targetPower > 0 ? myPower / targetPower : 99;

        // 根据战力比判断战斗结果描述
        let battleOutcome = '';
        let resultDescription = '';
        let notificationType = 'info';

        if (ratio > 2.0) {
            // 完全碾压
            battleOutcome = '完全碾压';
            resultDescription = '我的实力远超对方，战斗轻松取胜';
            notificationType = 'success';
        } else if (ratio >= 1.5) {
            // 优势明显
            battleOutcome = '优势明显';
            resultDescription = '我实力明显占优，战斗取得胜利';
            notificationType = 'success';
        } else if (ratio >= 1.2) {
            // 略占上风
            battleOutcome = '略占上风';
            resultDescription = '我略微占优，经过一番激战获胜';
            notificationType = 'success';
        } else if (ratio >= 0.9) {
            // 势均力敌
            battleOutcome = '势均力敌';
            resultDescription = '双方实力相当，战斗结果难以预料';
            notificationType = 'warning';
        } else if (ratio >= 0.67) {
            // 略处下风
            battleOutcome = '略处下风';
            resultDescription = '对方实力稍强，战斗陷入苦战';
            notificationType = 'warning';
        } else if (ratio >= 0.5) {
            // 劣势明显
            battleOutcome = '劣势明显';
            resultDescription = '对方实力明显更强，战斗极其艰难';
            notificationType = 'error';
        } else {
            // 难以匹敌
            battleOutcome = '难以匹敌';
            resultDescription = '对方实力远超于我，战斗几乎没有胜算';
            notificationType = 'error';
        }

        // 构建攻击消息
        const message = `<Request:Meta-instructions：接下来你要，按照当前剧情，设计一段与${characterName}战斗的故事，我的战斗力为${myPower}，对方战斗力为${targetPower}，战力对比为【${battleOutcome}】，${resultDescription}，注意更新变量> 对${characterName}发起攻击`;

        // 发送消息
        await triggerSlash(`/send ${message}`);
        await triggerSlash('/trigger');

        console.log('[Target Attack] 攻击请求已发送');

        // 显示不同类型的提示
        if (typeof toastr !== 'undefined') {
            const toastMessage = `正在对${characterName}发起攻击...\n战力比: ${ratio.toFixed(2)} (${battleOutcome})`;

            if (notificationType === 'success') {
                toastr.success(toastMessage, '攻击', { timeOut: 3000 });
            } else if (notificationType === 'warning') {
                toastr.warning(toastMessage, '攻击', { timeOut: 3000 });
            } else {
                toastr.error(toastMessage, '攻击', { timeOut: 3000 });
            }
        }
    } catch (error) {
        console.error('[Target Attack] 攻击失败:', error);
        throw error;
    }
};

// ========== 拍卖行功能 ==========
// 购买物品
window.handleBuyItem = async function(itemKey, itemName, itemPrice, itemCategory) {
    console.log(`💰 开始购买物品: ${itemName}, 价格: ${itemPrice}...`);

    try {
        // 获取当前数据
        let targetMessageId = 'latest';
        if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
            let currentId = getLastMessageId();
            while (currentId >= 0) {
                const message = getChatMessages(currentId).at(-1);
                if (message && message.role !== 'user') {
                    targetMessageId = currentId;
                    break;
                }
                currentId--;
            }
        }

        const mvuData = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });

        if (!mvuData || !mvuData.stat_data) {
            toastr.error('购买失败：无法获取数据');
            return;
        }

        // 检查灵石是否足够
        const lingshi = mvuData.stat_data['家族信息']?.['灵石']?.[0] || 0;
        if (lingshi < itemPrice) {
            toastr.warning('灵石不足！');
            return;
        }

        // 获取拍卖行物品的完整信息
        const auctionItemData = mvuData.stat_data['拍卖行']?.[itemCategory]?.[itemKey];

        if (!auctionItemData) {
            toastr.error('购买失败：物品数据不存在');
            return;
        }

        // 创建物品副本，去掉价格字段
        const itemDataForInventory = { ...auctionItemData };
        delete itemDataForInventory['价格'];

        // 1. 添加到道具仓库
        const currentItems = mvuData.stat_data['道具']?.[itemCategory] || {};
        const newItems = { ...currentItems };
        newItems[itemKey] = itemDataForInventory;

        await Mvu.setMvuVariable(mvuData, `道具.${itemCategory}`, newItems, { 
            reason: '从拍卖行购买物品', 
            is_recursive: false 
        });

        // 2. 从拍卖行删除
        await Mvu.setMvuVariable(mvuData, `拍卖行.${itemCategory}.${itemKey}`, null, { 
            reason: '物品已被购买', 
            is_recursive: false 
        });

        // 3. 扣除灵石
        const newLingshi = lingshi - itemPrice;
        await Mvu.setMvuVariable(mvuData, `家族信息.灵石[0]`, newLingshi, { 
            reason: '购买物品花费灵石', 
            is_recursive: false 
        });

        // 保存更新
        await Mvu.replaceMvuData(mvuData, { type: 'message', message_id: targetMessageId });

        console.log('✅ 购买成功');

        if (typeof toastr !== 'undefined') {
            toastr.success(`成功购买【${itemName}】，花费${itemPrice}灵石`, '购买成功', {
                timeOut: 2000
            });
        }

        // 刷新显示
        setTimeout(() => {
            loadAndDisplay();
        }, 500);

    } catch (error) {
        console.error('[Buy Item] 购买失败:', error);
        throw error;
    }
};

// 我要拍卖
window.handleMyAuction = async function() {
    console.log('📦 开始拍卖流程...');

    try {
        // 获取当前数据
        let targetMessageId = 'latest';
        if (typeof getLastMessageId === 'function' && typeof getChatMessages === 'function') {
            let currentId = getLastMessageId();
            while (currentId >= 0) {
                const message = getChatMessages(currentId).at(-1);
                if (message && message.role !== 'user') {
                    targetMessageId = currentId;
                    break;
                }
                currentId--;
            }
        }

        const data = Mvu.getMvuData({ type: 'message', message_id: targetMessageId });
        if (!data || !data.stat_data) {
            if (typeof toastr !== 'undefined') {
                toastr.error('无法获取道具数据');
            }
            return;
        }

        const itemsData = data.stat_data['道具'];
        if (!itemsData) {
            if (typeof toastr !== 'undefined') {
                toastr.warning('暂无可拍卖的道具');
            }
            return;
        }

        // 收集所有道具
        const allItems = [];
        const categories = ['灵资', '法器', '杂物', '功法', '法术'];

        categories.forEach(category => {
            const categoryData = itemsData[category];
            if (categoryData) {
                const itemKeys = Object.keys(categoryData).filter(k => k !== '$meta' && categoryData[k] !== null);
                itemKeys.forEach(key => {
                    const item = categoryData[key];
                    const name = item.名称?.[0] || key;
                    const count = item.数量?.[0] || 0;
                    if (count > 0) {
                        allItems.push({
                            key,
                            name,
                            count,
                            category
                        });
                    }
                });
            }
        });

        if (allItems.length === 0) {
            if (typeof toastr !== 'undefined') {
                toastr.warning('暂无可拍卖的道具');
            }
            return;
        }

        // 创建弹窗选择道具
        const modal = $(`
            <div style="
                position: fixed;
                top: 0;
                left: 0;
                right: 0;
                bottom: 0;
                background: rgba(0, 0, 0, 0.7);
                display: flex;
                align-items: center;
                justify-content: center;
                z-index: 9999;
            ">
                <div style="
                    background: linear-gradient(135deg, #1e2430 0%, #2a2f3f 100%);
                    border: 1px solid rgba(255, 255, 255, 0.1);
                    border-radius: 20px;
                    padding: 30px;
                    max-width: 500px;
                    width: 90%;
                    max-height: 70vh;
                    overflow: hidden;
                    display: flex;
                    flex-direction: column;
                    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
                ">
                    <h3 style="
                        color: #fbbf24;
                        margin: 0 0 20px 0;
                        font-size: 20px;
                        font-weight: 600;
                        text-align: center;
                    ">📦 选择要拍卖的物品</h3>

                    <div style="
                        flex: 1;
                        overflow-y: auto;
                        margin-bottom: 20px;
                        padding-right: 10px;
                    ">
                        ${allItems.map(item => `
                            <label style="
                                display: flex;
                                align-items: center;
                                padding: 12px;
                                background: rgba(255, 255, 255, 0.05);
                                border-radius: 8px;
                                margin-bottom: 8px;
                                cursor: pointer;
                                transition: all 0.3s;
                            " onmouseover="this.style.background='rgba(251, 191, 36, 0.1)'" onmouseout="this.style.background='rgba(255, 255, 255, 0.05)'">
                                <input type="checkbox" class="auction-item-checkbox" data-item-key="${item.key}" data-item-name="${item.name}" data-item-category="${item.category}" style="
                                    margin-right: 12px;
                                    width: 18px;
                                    height: 18px;
                                    cursor: pointer;
                                ">
                                <div style="flex: 1;">
                                    <div style="color: #e5e7eb; font-weight: 600; margin-bottom: 4px;">${item.name}</div>
                                    <div style="color: #9ca3af; font-size: 14px;">${item.category} | 数量: ${item.count}</div>
                                </div>
                            </label>
                        `).join('')}
                    </div>

                    <div style="display: flex; gap: 12px;">
                        <button id="auction-cancel-btn" style="
                            flex: 1;
                            padding: 12px;
                            background: rgba(156, 163, 175, 0.2);
                            border: 1px solid rgba(156, 163, 175, 0.3);
                            border-radius: 10px;
                            color: #9ca3af;
                            font-size: 14px;
                            font-weight: 600;
                            cursor: pointer;
                            transition: all 0.3s;
                        ">取消</button>
                        <button id="auction-confirm-btn" style="
                            flex: 1;
                            padding: 12px;
                            background: linear-gradient(135deg, rgba(251, 191, 36, 0.3), rgba(245, 158, 11, 0.3));
                            border: 1px solid rgba(251, 191, 36, 0.5);
                            border-radius: 10px;
                            color: #fbbf24;
                            font-size: 14px;
                            font-weight: 600;
                            cursor: pointer;
                            transition: all 0.3s;
                        ">确定拍卖</button>
                    </div>
                </div>
            </div>
        `);

        $('body').append(modal);

        // 取消按钮
        modal.find('#auction-cancel-btn').on('click', function() {
            modal.remove();
        });

        // 确定按钮
        modal.find('#auction-confirm-btn').on('click', async function() {
            const selectedItems = [];
            modal.find('.auction-item-checkbox:checked').each(function() {
                selectedItems.push({
                    key: $(this).data('item-key'),
                    name: $(this).data('item-name'),
                    category: $(this).data('item-category')
                });
            });

            if (selectedItems.length === 0) {
                if (typeof toastr !== 'undefined') {
                    toastr.warning('请至少选择一件物品');
                }
                return;
            }

            modal.remove();

            // 构建拍卖消息
            const itemsText = selectedItems.map(item => item.name).join('、');
            const message = `<Request:Meta-instructions：接下来你要，按照当前剧情，设计一段拍卖的故事，我想把${itemsText}拍卖出去，注意更新道具变量和灵石变量> 我将${itemsText}拍卖出去`;

            // 检查 triggerSlash 函数是否存在
            if (typeof triggerSlash !== 'function') {
                console.error('[My Auction] triggerSlash 函数不可用');
                if (typeof toastr !== 'undefined') {
                    toastr.error('操作失败：系统函数不可用');
                }
                return;
            }

            // 发送消息
            await triggerSlash(`/send ${message}`);
            await triggerSlash('/trigger');

            console.log('[My Auction] 拍卖请求已发送');

            if (typeof toastr !== 'undefined') {
                toastr.success(`开始拍卖${itemsText}...`, '拍卖', {
                    timeOut: 2000
                });
            }
        });

    } catch (error) {
        console.error('[My Auction] 拍卖失败:', error);
        throw error;
    }
};

